use clap::{Arg, Command};
use regex::Regex;
use serde_json::{json, Value};
use std::collections::{BTreeMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::net::{Ipv4Addr, Ipv6Addr};
use std::str::FromStr;

#[derive(Debug, Clone, PartialEq)]
enum Draft {
    D4,
    D6,
    D7,
    D2019,
    D2020,
}

fn parse_draft_str(s: &str) -> Option<Draft> {
    match s {
        "4" => Some(Draft::D4),
        "6" => Some(Draft::D6),
        "7" => Some(Draft::D7),
        "2019" => Some(Draft::D2019),
        "2020" => Some(Draft::D2020),
        _ => None,
    }
}

fn detect_draft_from_schema_str(s: &str) -> Option<Draft> {
    if s.contains("draft-04") {
        Some(Draft::D4)
    } else if s.contains("draft-06") {
        Some(Draft::D6)
    } else if s.contains("draft-07") {
        Some(Draft::D7)
    } else if s.contains("2019-09") {
        Some(Draft::D2019)
    } else if s.contains("2020-12") {
        Some(Draft::D2020)
    } else {
        None
    }
}

fn parse_seconds(s: &str) -> Result<f64, String> {
    s.parse::<f64>().map_err(|_| format!("'{}' is not a valid number", s))
}

fn value_to_string(v: &Value) -> String {
    // Serialize as json, but for string it will include quotes which we need?
    // For error messages, instance is displayed as json serialized string (e.g., 123, "y", [], etc.)
    // serde_json to_string gives exactly that.
    // For numbers, it will be like 123, -5, etc.
    // For strings, it will be quoted: "\"y\""
    // But for const expected message "5 was expected" it uses raw value? Actually const error "5 was expected" uses expected const value as raw? Let's see: const 5 instance 6 -> "5 was expected" (no quotes for number). const "a" instance "b" -> "\"a\" was expected". So it uses json serialization as well.
    serde_json::to_string(v).unwrap_or_else(|_| format!("{:?}", v))
}

fn json_pointer_escape(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

// Format validation helpers
fn is_valid_email(s: &str) -> bool {
    // Very simple check matching original's behavior for test cases: must contain @ and .
    // Original likely uses more complex, but let's do simple: one @, no spaces, at least one dot after @
    if s.contains(' ') { return false; }
    let parts: Vec<&str> = s.split('@').collect();
    if parts.len() != 2 { return false; }
    let local = parts[0];
    let domain = parts[1];
    if local.is_empty() || domain.is_empty() { return false; }
    if !domain.contains('.') { return false; }
    // No consecutive dots, etc.
    true
}

fn is_valid_date_time(s: &str) -> bool {
    // Try chrono rfc3339
    // chrono's parse_from_rfc3339 handles date-time
    chrono::DateTime::parse_from_rfc3339(s).is_ok()
}

fn is_valid_date(s: &str) -> bool {
    chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d").is_ok()
}

fn is_valid_time(s: &str) -> bool {
    // Time format: e.g., "20:20:39+00:00" or "20:20:39Z"
    // Try parse with chrono
    // chrono time parsing is tricky, we try multiple formats
    if chrono::NaiveTime::parse_from_str(s, "%H:%M:%S").is_ok() { return true; }
    if chrono::NaiveTime::parse_from_str(s, "%H:%M:%S%.f").is_ok() { return true; }
    // with offset
    if let Ok(_) = chrono::DateTime::parse_from_str(s, "%H:%M:%S%:z") { return true; }
    if let Ok(_) = chrono::DateTime::parse_from_str(s, "%H:%M:%S%.f%:z") { return true; }
    // Try with Z
    if s.ends_with('Z') {
        let without_z = &s[..s.len()-1];
        if chrono::NaiveTime::parse_from_str(without_z, "%H:%M:%S").is_ok() { return true; }
        if chrono::NaiveTime::parse_from_str(without_z, "%H:%M:%S%.f").is_ok() { return true; }
    }
    // Also try parsing as time with offset like +00:00
    // Use chrono's parse
    // For simplicity, use regex: HH:MM:SS with optional fraction and timezone
    // We'll try to use chrono's FixedOffset parsing via DateTime then extract time part?
    // For our purposes, test cases: "20:20:39+00:00" should be valid.
    // Let's try to parse using chrono's NaiveTime + offset handling manually
    // If contains '+' or second occurrence of '-' after time, we split
    // Simplify: if string contains 'T' it's date-time, not time, so we already handled.
    // We'll use a simple regex for time
    let re = Regex::new(r"^\d{2}:\d{2}:\d{2}(\.\d+)?(Z|[+-]\d{2}:\d{2})?$").unwrap();
    re.is_match(s)
}

fn is_valid_uri(s: &str) -> bool {
    url::Url::parse(s).is_ok()
}

fn is_valid_uri_reference(s: &str) -> bool {
    // uri-reference can be relative, so we try Url::parse, and if fails, try with fake base
    if url::Url::parse(s).is_ok() { return true; }
    // Try relative: url::Url::options().base_url(Some(&url::Url::parse("http://example.com").unwrap())).parse(s).is_ok()
    // For simplicity, consider any string without spaces as valid? But original: "not a uri" invalid, but "https://example.com" valid.
    // "not a uri" contains spaces, so invalid. For relative, maybe "a/b" should be valid? Original for uri-reference? Let's assume same as uri plus relative paths without spaces.
    !s.contains(' ') && !s.is_empty()
}

fn is_valid_ipv4(s: &str) -> bool {
    Ipv4Addr::from_str(s).is_ok()
}

fn is_valid_ipv6(s: &str) -> bool {
    Ipv6Addr::from_str(s).is_ok()
}

fn is_valid_hostname(s: &str) -> bool {
    // Simple: must not contain spaces, must contain at least one dot? But test "example.com" valid. Let's check simple.
    if s.is_empty() || s.len() > 253 { return false; }
    if s.contains(' ') { return false; }
    // Must be valid domain: labels separated by dot, each label alphanumeric hyphen, not starting/ending with hyphen
    let re = Regex::new(r"^(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$").unwrap();
    // Also allow single label? For simplicity, also allow without dot? But spec says hostname should have at least one dot? We'll allow both.
    if re.is_match(s) { return true; }
    // Check single label hostname
    let re2 = Regex::new(r"^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$").unwrap();
    re2.is_match(s)
}

fn is_valid_format(fmt: &str, value: &str) -> bool {
    match fmt {
        "email" => is_valid_email(value),
        "idn-email" => is_valid_email(value), // simplified
        "date-time" => is_valid_date_time(value),
        "date" => is_valid_date(value),
        "time" => is_valid_time(value),
        "uri" => is_valid_uri(value),
        "uri-reference" => is_valid_uri_reference(value),
        "iri" => is_valid_uri(value),
        "iri-reference" => is_valid_uri_reference(value),
        "ipv4" => is_valid_ipv4(value),
        "ipv6" => is_valid_ipv6(value),
        "hostname" => is_valid_hostname(value),
        "idn-hostname" => is_valid_hostname(value),
        "json-pointer" => {
            // Must be empty or start with /
            if value.is_empty() { true } else { value.starts_with('/') }
        },
        "relative-json-pointer" => {
            // Simplified: starts with number
            let re = Regex::new(r"^\d+(#|/.*)?$").unwrap();
            re.is_match(value)
        },
        "regex" => {
            Regex::new(value).is_ok()
        },
        "uuid" => {
            // Check uuid format
            let re = Regex::new(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$").unwrap();
            re.is_match(value)
        },
        _ => true, // unknown format considered valid
    }
}

// Output structures for list/hierarchical
#[derive(Debug, Clone)]
struct OutputNode {
    evaluation_path: String,
    instance_location: String,
    schema_location: String,
    valid: bool,
    errors: Option<BTreeMap<String, Value>>, // key -> message string or array
    annotations: Option<Value>, // could be array or object, simplified as Value
    dropped_annotations: Option<Value>,
    details: Vec<OutputNode>,
}

impl OutputNode {
    fn to_list_json(&self, schema_id_base: &str) -> Value {
        // For list output, we flatten tree into list via BFS? Original list order seems to be DFS pre-order?
        // Let's implement DFS pre-order that includes root and all descendants.
        // Actually list output includes root first, then children in order.
        // For hierarchical, it's nested.
        // We'll generate list by traversing.
        let mut list = Vec::new();
        self.collect_list(&mut list);
        // Convert each node to JSON object with relevant fields
        let details: Vec<Value> = list.into_iter().map(|node| node.to_json_object()).collect();
        let valid = self.valid;
        json!({
            "details": details,
            "valid": valid
        })
    }

    fn collect_list<'a>(&'a self, out: &mut Vec<&'a OutputNode>) {
        out.push(self);
        for child in &self.details {
            child.collect_list(out);
        }
    }

    fn to_json_object(&self) -> Value {
        let mut map = serde_json::Map::new();
        if let Some(errs) = &self.errors {
            // errors is BTreeMap<String, Value>
            let mut err_map = serde_json::Map::new();
            for (k, v) in errs {
                err_map.insert(k.clone(), v.clone());
            }
            map.insert("errors".to_string(), Value::Object(err_map));
        }
        if let Some(ann) = &self.annotations {
            map.insert("annotations".to_string(), ann.clone());
        }
        if let Some(dropped) = &self.dropped_annotations {
            map.insert("droppedAnnotations".to_string(), dropped.clone());
        }
        map.insert("evaluationPath".to_string(), Value::String(self.evaluation_path.clone()));
        map.insert("instanceLocation".to_string(), Value::String(self.instance_location.clone()));
        map.insert("schemaLocation".to_string(), Value::String(self.schema_location.clone()));
        map.insert("valid".to_string(), Value::Bool(self.valid));
        Value::Object(map)
    }

    fn to_hierarchical_json(&self) -> Value {
        // For hierarchical, root's evaluationPath is "" but its details contain children.
        // Actually hierarchical output has root details containing children, and root's own valid, etc.
        // The structure we built should already have details nested.
        // So we produce JSON for this node including its details recursively as hierarchical.
        let mut map = serde_json::Map::new();
        if !self.details.is_empty() {
            let details: Vec<Value> = self.details.iter().map(|d| d.to_hierarchical_json()).collect();
            map.insert("details".to_string(), Value::Array(details));
        }
        if let Some(errs) = &self.errors {
            let mut err_map = serde_json::Map::new();
            for (k, v) in errs {
                err_map.insert(k.clone(), v.clone());
            }
            map.insert("errors".to_string(), Value::Object(err_map));
        }
        if let Some(ann) = &self.annotations {
            map.insert("annotations".to_string(), ann.clone());
        }
        if let Some(dropped) = &self.dropped_annotations {
            map.insert("droppedAnnotations".to_string(), dropped.clone());
        }
        map.insert("evaluationPath".to_string(), Value::String(self.evaluation_path.clone()));
        map.insert("instanceLocation".to_string(), Value::String(self.instance_location.clone()));
        map.insert("schemaLocation".to_string(), Value::String(self.schema_location.clone()));
        map.insert("valid".to_string(), Value::Bool(self.valid));
        Value::Object(map)
    }

    fn to_payload_hierarchical(&self) -> Value {
        // For hierarchical output, payload is the root node's hierarchical json (but root itself is the outermost)
        // Actually original hierarchical payload has evaluationPath "", instanceLocation "", schemaLocation base, valid bool, and details array.
        // Our root node already represents that.
        // So we produce its hierarchical json, but if root has no details? It should still have details? For valid case, root may have details.
        // For simplicity, we will return root's hierarchical json as payload if root evaluationPath is "".
        // But if our root is the topmost, its to_hierarchical_json already includes evaluationPath "".
        // For payload, we need to produce object with details, valid, etc. That's exactly to_hierarchical_json except if we want to include annotations of root?
        // Original hierarchical payload for valid case had details array containing type, required, properties etc, and root valid true.
        // So our root node's hierarchical json is sufficient.
        // However, for list output, payload is {details: [...], valid: bool} where details includes root and all.
        // For hierarchical, payload is root node itself (with details nested), not wrapped in extra.
        // Let's check original: for hierarchical, payload had evaluationPath "", instanceLocation "", schemaLocation "...", valid bool, details array.
        // That's exactly root node.
        // So we can return root's hierarchical json as payload.
        self.to_hierarchical_json()
    }
}

// Validation context
struct ValidationContext {
    draft: Draft,
    assert_format: bool,
    schema_id_base: String, // e.g., file:///tmp/schema.json# or https://example.com/...
    base_dir: PathBuf, // directory of schema file for resolving relative file refs
    root_schema: Value, // for $ref resolution
}

fn resolve_json_pointer<'a>(root: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() || pointer == "#" {
        return Some(root);
    }
    let mut p = pointer;
    if p.starts_with('#') {
        p = &p[1..];
    }
    // p should start with / or be empty
    let mut current = root;
    if p.is_empty() {
        return Some(current);
    }
    for token in p.split('/').skip(1) { // split by '/', first element empty because starts with /
        let token = token.replace("~1", "/").replace("~0", "~");
        match current {
            Value::Object(map) => {
                current = map.get(&token)?;
            }
            Value::Array(arr) => {
                let idx: usize = token.parse().ok()?;
                current = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(current)
}

fn resolve_ref(schema: &Value, ctx: &ValidationContext, ref_str: &str) -> Option<(Value, String)> {
    // ref_str could be like "#/definitions/foo" or "def.json" or "def.json#/something" or file://
    // For simplicity, handle:
    // - If starts with "#": internal pointer
    // - Else if contains "#": split file part and pointer
    // - Else file part only
    if ref_str.starts_with('#') {
        if let Some(target) = resolve_json_pointer(&ctx.root_schema, ref_str) {
            // schemaLocation for target? We'll keep same base but with ref path? Actually schemaLocation should be base + ref_str?
            // For simplicity, we return value and schema_location as base + ref_str? But original for internal ref used file://...#/definitions/foo as schemaLocation for $ref evaluation? Let's check earlier: for $ref "#/definitions/foo", schemaLocation for $ref type was file:///tmp/s.json#/definitions/foo/type . So evaluationPath "/$ref/type" but schemaLocation file:///tmp/s.json#/definitions/foo/type
            // So when resolving #/definitions/foo, the base schemaLocation for that sub-schema should be base + "/definitions/foo" etc.
            // We'll handle in validation: when we encounter $ref, we resolve and we know the ref path.
            // Return value cloned
            return Some((target.clone(), ref_str.to_string()));
        }
        None
    } else {
        // External file
        let (file_part, pointer_part) = if let Some(idx) = ref_str.find('#') {
            (&ref_str[..idx], &ref_str[idx..])
        } else {
            (ref_str, "")
        };
        // Resolve file_part relative to base_dir
        let file_path = if Path::new(file_part).is_absolute() {
            PathBuf::from(file_part)
        } else {
            ctx.base_dir.join(file_part)
        };
        // Try to read file
        if let Ok(content) = fs::read_to_string(&file_path) {
            if let Ok(val) = serde_json::from_str::<Value>(&content) {
                if pointer_part.is_empty() {
                    // Return val, with file path as base for schemaLocation?
                    // For simplicity, return val
                    return Some((val, file_path.to_string_lossy().to_string()));
                } else {
                    if let Some(target) = resolve_json_pointer(&val, pointer_part) {
                        return Some((target.clone(), format!("{}#{}", file_part, pointer_part)));
                    }
                }
            }
        }
        None
    }
}

fn is_type(value: &Value, expected: &str) -> bool {
    match expected {
        "null" => value.is_null(),
        "boolean" => value.is_boolean(),
        "object" => value.is_object(),
        "array" => value.is_array(),
        "number" => value.is_number(),
        "string" => value.is_string(),
        "integer" => {
            if let Some(n) = value.as_i64() {
                true
            } else if let Some(n) = value.as_u64() {
                true
            } else if let Some(n) = value.as_f64() {
                // Check if integer value
                n.fract() == 0.0
            } else {
                false
            }
        }
        _ => false,
    }
}

fn format_expected_types(types: &[String]) -> String {
    // For error messages: e.g., "\"integer\", \"string\"" ?
    // Original for multi types: "true is not of types \"integer\", \"string\""
    // It lists types quoted.
    // For single type: "true is not of type \"string\""
    // We need to handle.
    if types.is_empty() {
        return String::new();
    }
    if types.len() == 1 {
        format!("\"{}\"", types[0])
    } else {
        // Join with ", " and quote each
        let quoted: Vec<String> = types.iter().map(|t| format!("\"{}\"", t)).collect();
        quoted.join(", ")
    }
}

