fn resolve_json_pointer<'a>(root: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() || pointer == "#" {
        return Some(root);
    }
    let mut p = pointer;
    if p.starts_with('#') {
        p = &p[1..];
    }
    // p should start with / or be empty
    let mut current = root;
    if p.is_empty() {
        return Some(current);
    }
    for token in p.split('/').skip(1) { // split by '/', first element empty because starts with /
        let token = token.replace("~1", "/").replace("~0", "~");
        match current {
            Value::Object(map) => {
                current = map.get(&token)?;
            }
            Value::Array(arr) => {
                let idx: usize = token.parse().ok()?;
                current = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(current)
}

fn resolve_ref(schema: &Value, ctx: &ValidationContext, ref_str: &str) -> Option<(Value, String)> {
    // ref_str could be like "#/definitions/foo" or "def.json" or "def.json#/something" or file://
