            // We'll handle in validation: when we encounter $ref, we resolve and we know the ref path.
            // Return value cloned
            return Some((target.clone(), ref_str.to_string()));
        }
        None
    } else {
        // External file
        let (file_part, pointer_part) = if let Some(idx) = ref_str.find('#') {
            (&ref_str[..idx], &ref_str[idx..])
        } else {
            (ref_str, "")
        };
        // Resolve file_part relative to base_dir
        let file_path = if Path::new(file_part).is_absolute() {
            PathBuf::from(file_part)
        } else {
            ctx.base_dir.join(file_part)
        };
        // Try to read file
