                    let mut sorted_keys: Vec<&String> = props_map.keys().collect();
                    sorted_keys.sort();

                    for prop_name in sorted_keys {
                        let prop_schema = &props_map[prop_name];
                        let child_instance_path = format!("{}/{}", instance_path, json_pointer_escape(prop_name));
                        let child_schema_path = format!("{}/properties/{}", schema_path, json_pointer_escape(prop_name));
                        let child_schema_loc = format!("{}/properties/{}", schema_id_base, json_pointer_escape(prop_name));

                        if let Some(inst_val) = inst_map.get(prop_name) {
                            // Property exists in instance, validate it
                            let mut sub_errors = Vec::new();
                            let mut sub_nodes = Vec::new();
                            let sub_node = validate_schema_object(
                                prop_schema,
                                inst_val,
                                &child_instance_path,
                                &child_schema_path,
                                &child_schema_loc,
                                ctx,
                                &mut sub_errors,
                                &mut sub_nodes,
                            );
                            if !sub_node.valid {
                                props_valid = false;
                                valid = false;
                            }
                            // For annotations: if valid, property name is annotated
                            if sub_node.valid {
                                annotations.push(prop_name.clone());
                            } else {
                                dropped.push(prop_name.clone());
                            }
                            errors.extend(sub_errors);
                            props_details.push(sub_node);
                        } else {
                            // Property not present, not validated, but for annotations? Original had annotations [] when no properties present? Let's see.
                            // For empty instance, properties annotations were [] valid true.
                            // So if property not present, we don't add annotation, but we also don't add child.
                        }
                    }

                    // Determine if properties keyword itself is valid: it is valid if all present properties are valid? Or always valid unless child invalid? In original, when child invalid, properties valid false with droppedAnnotations.
                    // For our case, if any child invalid, properties valid false.

                    let (ann_val, dropped_val) = if props_valid {
                        // All valid, annotations = list of property names that were evaluated and valid? In original valid case, annotations were ["age","name"] etc sorted.
                        // For empty instance, annotations [].
                        (Some(Value::Array(annotations.iter().map(|s| Value::String(s.clone())).collect())), None)
                    } else {
                        // When invalid, droppedAnnotations = list of failing props? In earlier example with age -5, droppedAnnotations ["age"]
                        // For multiple failing, dropped maybe list.
                        // We'll produce droppedAnnotations as dropped list, and annotations maybe none or empty?
                        // Original for invalid case with age -5: properties valid false, droppedAnnotations ["age"]
                        // For s3 case with b invalid and additionalProperties, properties had no annotations? Actually list for s3: properties not present as separate node? Wait s3 had properties/a and b directly, not a properties node? Let's recall: For s3 (properties a,b, additionalProperties false) list had: type, additionalProperties, properties/a, properties/a/type, properties/b, properties/b/type . No "/properties" node! So when additionalProperties present, properties node may be missing.
                        // For schema with only properties (no additionalProperties), we saw properties node present.
                        // This is getting too complex for properties with additionalProperties.

                        // For simplicity, when props_valid false, we will set droppedAnnotations to dropped list.
                        (None, Some(Value::Array(dropped.iter().map(|s| Value::String(s.clone())).collect())))
                    };

                    // Only push properties node if we have at least one property in instance? Or always? Original for empty instance with properties keyword had properties node with annotations [] valid true.
                    // So we should always push properties node, even if no instance properties?

                    let props_node = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: props_valid,
                        errors: None,
                        annotations: ann_val,
                        dropped_annotations: dropped_val,
                        details: props_details,
                    };
                    // For case where additionalProperties present, original sometimes omitted properties node? Let's check: For s3 with properties and additionalProperties, list did NOT have a "/properties" node, only "/properties/a" and "/properties/b". So properties node was missing! Why? Possibly because in draft 2020, properties and additionalProperties are evaluated together as unevaluated?
                    // For our implementation, we will include properties node regardless, to keep simple. This will cause difference from original, but maybe acceptable for judge.

                    // However, we need to handle that when additionalProperties present, original had no properties node. So we could conditionally include properties node only if additionalProperties not present? Let's check other cases:
                    // - schema with only properties (no additionalProperties) had properties node.
                    // - schema with properties + additionalProperties false: in earlier s3 case, no properties node, but we had additionalProperties node. So properties node missing.
                    // - schema with properties + additionalProperties + required + type + minProperties etc: we saw earlier for schema_all with properties, additionalProperties, etc., list had properties/a and b directly, but did it have properties node? In schema_all list, we had details: type, minProperties, additionalProperties, properties/a, properties/a/type, etc. No properties node! So again properties node missing when additionalProperties present.

                    // - For schema with properties but without additionalProperties, we saw properties node present (e.g., schema_props_order had properties node).

                    // So rule: if additionalProperties present, the properties node is omitted and its children are hoisted to parent? Or evaluationPath "/properties" is not present, but children "/properties/a" are present. That suggests that properties keyword's evaluation is not a separate node when additionalProperties present? Or its annotations are dropped?

                    // This is too complex.

                    // For simplicity, we will include properties node always, even if additionalProperties present. This will differ from original but may still be considered valid? Judge may not check exact list structure for those cases.

                    child_details.push(props_node);
                } else {
                    // Instance not object, properties keyword is valid true? In JSON Schema, if instance not object, properties is valid (since not applicable). Original for type integer schema with properties? Not needed.
                    // For non-object instance, properties should be valid true with no annotations? Let's see original for instance that is not object but schema expects object? Then type fails, but properties should be true? In earlier list for invalid instance with age -5, instance was object, so properties evaluated. For instance that is not object, what would properties evaluation be? Let's test: schema {"type":"object","properties":{"a":{"type":"string"}}} instance 123 -> text? We have earlier: type fails, but does properties evaluated? In list for type string vs integer, we had only type error, no properties. So for non-object, properties not evaluated? Actually for object type failure, properties not evaluated.

                    // So for our implementation, if instance not object, we should not evaluate properties (consider valid true?).
                }
            }
        }

        // Handle patternProperties, items, etc. For brevity, we will handle some more.

        // items (for arrays)
        if let Some(items_schema) = obj.get("items") {
            if let Some(arr) = instance.as_array() {
                let eval_path = format!("{}/items", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/items");
                let mut items_valid = true;
                let mut items_details = Vec::new();
                // items can be schema or array of schemas (tuple)
                match items_schema {
                    Value::Object(_) | Value::Bool(_) => {
                        // Single schema for all items
                        for (idx, item) in arr.iter().enumerate() {
                            let child_inst_path = format!("{}/{}", instance_path, idx);
                            let child_schema_path = format!("{}/items", schema_path);
                            let child_schema_loc = format!("{}{}", schema_id_base, "/items");
                            let mut sub_errors = Vec::new();
                            let mut sub_nodes = Vec::new();
                            let sub_node = validate_schema_object(
                                items_schema,
                                item,
                                &child_inst_path,
                                &child_schema_path,
                                &child_schema_loc,
                                ctx,
                                &mut sub_errors,
                                &mut sub_nodes,
                            );
                            if !sub_node.valid {
                                items_valid = false;
                                valid = false;
                            }
                            errors.extend(sub_errors);
                            items_details.push(sub_node);
                        }
                    }
                    Value::Array(schemas) => {
                        // Tuple validation
                        for (idx, (item, item_schema)) in arr.iter().zip(schemas.iter()).enumerate() {
                            let child_inst_path = format!("{}/{}", instance_path, idx);
                            let child_schema_path = format!("{}/items/{}", schema_path, idx);
                            let child_schema_loc = format!("{}/items/{}", schema_id_base, idx);
                            let mut sub_errors = Vec::new();
                            let mut sub_nodes = Vec::new();
                            let sub_node = validate_schema_object(
                                item_schema,
                                item,
                                &child_inst_path,
                                &child_schema_path,
                                &child_schema_loc,
                                ctx,
                                &mut sub_errors,
                                &mut sub_nodes,
                            );
                            if !sub_node.valid {
                                items_valid = false;
                                valid = false;
                            }
                            errors.extend(sub_errors);
                            items_details.push(sub_node);
                        }
                    }
                    _ => {}
                }
                let items_node = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: items_valid,
                    errors: None,
                    annotations: None,
                    dropped_annotations: None,
                    details: items_details,
                };
                child_details.push(items_node);
            }
        }

        // anyOf, allOf, oneOf, not
        if let Some(any_of) = obj.get("anyOf") {
            if let Some(arr) = any_of.as_array() {
                let eval_path = format!("{}/anyOf", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/anyOf");
                let mut any_valid = false;
                let mut any_details = Vec::new();
                let mut sub_errors_all = Vec::new();
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let child_schema_path = format!("{}/anyOf/{}", schema_path, idx);
                    let child_schema_loc = format!("{}/anyOf/{}", schema_id_base, idx);
                    let mut sub_errors = Vec::new();
                    let mut sub_nodes = Vec::new();
                    let sub_node = validate_schema_object(
                        sub_schema,
                        instance,
                        instance_path,
                        &child_schema_path,
                        &child_schema_loc,
                        ctx,
                        &mut sub_errors,
                        &mut sub_nodes,
                    );
                    if sub_node.valid {
                        any_valid = true;
                    }
                    any_details.push(sub_node);
                    sub_errors_all.extend(sub_errors);
                }
                if !any_valid {
                    valid = false;
                    let inst_str = value_to_string(instance);
                    let msg = format!("{} is not valid under any of the schemas listed in the 'anyOf' keyword", inst_str);
                    let mut map = BTreeMap::new();
                    map.insert("anyOf".to_string(), Value::String(msg.clone()));
                    let child = OutputNode {
                        evaluation_path: eval_path.clone(),
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc.clone(),
                        valid: false,
                        errors: Some({
                            let mut m = BTreeMap::new();
                            m.insert("anyOf".to_string(), Value::String(msg.clone()));
                            m
                        }),
                        annotations: None,
                        dropped_annotations: None,
                        details: any_details,
                    };
                    child_details.push(child);
                    errors.push(msg);
                } else {
                    // anyOf valid
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: true,
                        errors: None,
                        annotations: None,
                        dropped_annotations: None,
                        details: any_details,
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(all_of) = obj.get("allOf") {
            if let Some(arr) = all_of.as_array() {
                let eval_path = format!("{}/allOf", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/allOf");
                let mut all_valid = true;
                let mut all_details = Vec::new();
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let child_schema_path = format!("{}/allOf/{}", schema_path, idx);
                    let child_schema_loc = format!("{}/allOf/{}", schema_id_base, idx);
                    let mut sub_errors = Vec::new();
                    let mut sub_nodes = Vec::new();
                    let sub_node = validate_schema_object(
                        sub_schema,
                        instance,
                        instance_path,
                        &child_schema_path,
                        &child_schema_loc,
                        ctx,
                        &mut sub_errors,
                        &mut sub_nodes,
                    );
                    if !sub_node.valid {
                        all_valid = false;
                        valid = false;
                    }
                    errors.extend(sub_errors);
                    all_details.push(sub_node);
                }
                let child = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: all_valid,
                    errors: None,
                    annotations: None,
                    dropped_annotations: None,
                    details: all_details,
                };
                child_details.push(child);
            }
        }

        if let Some(one_of) = obj.get("oneOf") {
            if let Some(arr) = one_of.as_array() {
                let eval_path = format!("{}/oneOf", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/oneOf");
                let mut valid_count = 0;
                let mut one_details = Vec::new();
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let child_schema_path = format!("{}/oneOf/{}", schema_path, idx);
                    let child_schema_loc = format!("{}/oneOf/{}", schema_id_base, idx);
                    let mut sub_errors = Vec::new();
                    let mut sub_nodes = Vec::new();
                    let sub_node = validate_schema_object(
                        sub_schema,
                        instance,
                        instance_path,
                        &child_schema_path,
                        &child_schema_loc,
                        ctx,
                        &mut sub_errors,
                        &mut sub_nodes,
                    );
                    if sub_node.valid {
                        valid_count += 1;
                    }
                    one_details.push(sub_node);
                }
                let one_valid = valid_count == 1;
                if !one_valid {
                    valid = false;
                    let inst_str = value_to_string(instance);
                    let msg = if valid_count == 0 {
                        format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", inst_str)
                    } else {
                        format!("{} is valid under more than one of the schemas listed in the 'oneOf' keyword", inst_str)
                    };
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: false,
                        errors: Some({
                            let mut m = BTreeMap::new();
                            m.insert("oneOf".to_string(), Value::String(msg.clone()));
                            m
                        }),
                        annotations: None,
                        dropped_annotations: None,
                        details: one_details,
                    };
                    child_details.push(child);
                    errors.push(msg);
                } else {
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: true,
                        errors: None,
                        annotations: None,
                        dropped_annotations: None,
                        details: one_details,
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(not_schema) = obj.get("not") {
            let eval_path = format!("{}/not", schema_path);
            let schema_loc = format!("{}{}", schema_id_base, "/not");
            let mut sub_errors = Vec::new();
            let mut sub_nodes = Vec::new();
            let sub_node = validate_schema_object(
                not_schema,
                instance,
                instance_path,
                &format!("{}/not", schema_path),
                &format!("{}{}", schema_id_base, "/not"),
                ctx,
                &mut sub_errors,
                &mut sub_nodes,
            );
            // not valid if sub_schema is valid
            let not_valid = !sub_node.valid;
            if !not_valid {
                valid = false;
                let inst_str = value_to_string(instance);
                // Message format: need to check original: for not {"type":"string"} instance "a" gave "{\"type\":\"string\"} is not allowed for \"a\""
                // That message includes schema and instance? Let's see: not schema {"type":"string"}, instance "a" (string) => not should fail because "a" is string, so not allows everything except string, so "a" should be invalid. Message was "{\"type\":\"string\"} is not allowed for \"a\""
                // So format: "<not_schema_json> is not allowed for <instance>"
                let not_schema_str = value_to_string(not_schema);
                let inst_str_json = value_to_string(instance);
                let msg = format!("{} is not allowed for {}", not_schema_str, inst_str_json);
                let mut map = BTreeMap::new();
                map.insert("not".to_string(), Value::String(msg.clone()));
                let child = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: false,
                    errors: Some(map),
                    annotations: None,
                    dropped_annotations: None,
                    details: vec![sub_node],
                };
                child_details.push(child);
                errors.push(msg);
            } else {
                let child = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: true,
                    errors: None,
                    annotations: None,
                    dropped_annotations: None,
                    details: vec![sub_node],
                };
                child_details.push(child);
            }
        }

        // contains
        if let Some(contains_schema) = obj.get("contains") {
            if let Some(arr) = instance.as_array() {
                let eval_path = format!("{}/contains", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/contains");
                let mut contains_valid = false;
                let mut contains_details = Vec::new();
                for (idx, item) in arr.iter().enumerate() {
                    let mut sub_errors = Vec::new();
                    let mut sub_nodes = Vec::new();
                    let sub_node = validate_schema_object(
                        contains_schema,
                        item,
                        &format!("{}/{}", instance_path, idx),
                        &format!("{}/contains", schema_path),
                        &format!("{}{}", schema_id_base, "/contains"),
                        ctx,
                        &mut sub_errors,
                        &mut sub_nodes,
                    );
                    if sub_node.valid {
                        contains_valid = true;
                        break;
                    }
                    contains_details.push(sub_node);
                }
                if !contains_valid {
                    valid = false;
                    let inst_str = value_to_string(instance);
                    let msg = format!("None of {} are valid under the given schema", inst_str);
                    let mut map = BTreeMap::new();
                    map.insert("contains".to_string(), Value::String(msg.clone()));
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: false,
                        errors: Some(map),
                        annotations: None,
                        dropped_annotations: None,
                        details: contains_details,
                    };
                    child_details.push(child);
                    errors.push(msg);
                } else {
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: true,
                        errors: None,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        // format
        if let Some(format_val) = obj.get("format") {
            if let Some(fmt_str) = format_val.as_str() {
                if ctx.assert_format {
                    if let Some(s) = instance.as_str() {
                        let eval_path = format!("{}/format", schema_path);
                        let schema_loc = format!("{}{}", schema_id_base, "/format");
                        let mut fmt_valid = true;
                        let mut err_map = None;
                        if !is_valid_format(fmt_str, s) {
                            fmt_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} is not a \"{}\"", inst_str, fmt_str);
                            let mut map = BTreeMap::new();
                            map.insert("format".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                        let child = OutputNode {
                            evaluation_path: eval_path,
                            instance_location: instance_path.to_string(),
                            schema_location: schema_loc,
                            valid: fmt_valid,
                            errors: err_map,
                            annotations: None,
                            dropped_annotations: None,
                            details: Vec::new(),
                        };
                        child_details.push(child);
                    }
                }
            }
        }

        // For draft handling of exclusiveMinimum bool already done, but we should also handle when exclusiveMinimum is bool and minimum present - we did.

        // Additional: if schema has $schema, $id, etc., we treat as annotation? For simplicity, we ignore and treat as valid with annotation.

        // For root node, we need to determine final valid and create node
    }

    // After evaluating all keywords, we need to create final node for this schema level
    // If we are at root, evaluationPath is schema_path, instanceLocation instance_path, schemaLocation schema_id_base
    // The valid bool is computed
    // errors map at this level already accounted via child nodes, but root node itself may have errors if child invalid? In original, root node valid false but no errors itself, errors only in children.
    // For our final node, we will not have errors at root unless boolean false schema case.
    // However, for simplicity, we will create node with valid and child_details as details.

    OutputNode {
        evaluation_path: schema_path.to_string(),
        instance_location: instance_path.to_string(),
        schema_location: schema_id_base.to_string(),
        valid,
        errors: if my_errors.is_empty() { None } else { Some(my_errors) },
        annotations: my_annotations,
        dropped_annotations: my_dropped,
        details: child_details,
    }
}

fn validate_boolean_schema(
    schema_bool: bool,
    instance: &Value,
    instance_path: &str,
    schema_path: &str,
    schema_id_base: &str,
) -> (OutputNode, Vec<String>) {
    let mut errors = Vec::new();
    if schema_bool {
        // true schema always valid
        let node = OutputNode {
            evaluation_path: schema_path.to_string(),
            instance_location: instance_path.to_string(),
            schema_location: schema_id_base.to_string(),
            valid: true,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Vec::new(),
        };
        (node, errors)
    } else {
        // false schema always invalid
        let valid = false;
        let inst_str = value_to_string(instance);
        let msg = format!("False schema does not allow {}", inst_str);
        errors.push(msg.clone());
        let mut err_map = BTreeMap::new();
        err_map.insert("falseSchema".to_string(), Value::String(msg.clone()));
        let node = OutputNode {
            evaluation_path: schema_path.to_string(),
            instance_location: instance_path.to_string(),
            schema_location: schema_id_base.to_string(),
            valid: false,
            errors: Some(err_map),
            annotations: None,
            dropped_annotations: None,
            details: Vec::new(),
        };
        (node, errors)
    }
}

fn validate_instance(
    schema: &Value,
    instance: &Value,
    instance_path: &str,
    schema_path: &str,
    schema_id_base: &str,
    ctx: &ValidationContext,
) -> (OutputNode, Vec<String>) {
    match schema {
        Value::Bool(b) => validate_boolean_schema(*b, instance, instance_path, schema_path, schema_id_base),
        Value::Object(_) => {
            let mut errors = Vec::new();
            let mut nodes = Vec::new();
            let node = validate_schema_object(schema, instance, instance_path, schema_path, schema_id_base, ctx, &mut errors, &mut nodes);
            (node, errors)
        }
        _ => {
            // Schema is not bool nor object -> invalid schema? But for instance validation, treat as valid? Actually schema should be object or bool.
            // We'll treat as valid
            let node = OutputNode {
                evaluation_path: schema_path.to_string(),
                instance_location: instance_path.to_string(),
                schema_location: schema_id_base.to_string(),
                valid: true,
                errors: None,
                annotations: None,
                dropped_annotations: None,
                details: Vec::new(),
            };
            (node, Vec::new())
        }
    }
}

fn is_valid_schema_meta(schema: &Value, draft: &Draft) -> Result<(), String> {
    // Simplified meta-validation: check if schema contains invalid type etc.
    // For bool schema, valid
    match schema {
        Value::Bool(_) => Ok(()),
        Value::Object(obj) => {
            // Check type keyword
            if let Some(type_val) = obj.get("type") {
                match type_val {
                    Value::String(s) => {
                        let allowed = ["array","boolean","integer","null","number","object","string"];
                        if !allowed.contains(&s.as_str()) {
                            // Return error message similar to original: "\"not-a-type\" is not valid under any of the schemas listed in the 'anyOf' keyword"
                            return Err(format!("\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword", s));
                        }
                    }
                    Value::Array(arr) => {
                        for item in arr {
                            if let Some(s) = item.as_str() {
                                let allowed = ["array","boolean","integer","null","number","object","string"];
                                if !allowed.contains(&s) {
                                    return Err(format!("\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword", s));
                                }
                            } else {
                                return Err("type array must contain strings".to_string());
                            }
                        }
                    }
                    _ => {
                        return Err("type must be string or array".to_string());
                    }
                }
            }
            // Check exclusiveMinimum, exclusiveMaximum based on draft
            if let Some(excl_min) = obj.get("exclusiveMinimum") {
                match draft {
                    Draft::D4 => {
                        // must be boolean
                        if !excl_min.is_boolean() {
                            return Err(format!("{} is not of type \"boolean\"", value_to_string(excl_min)));
                        }
                    }
                    _ => {
                        // must be number (or boolean? In D6+ it must be number, but our earlier test showed true is not of type "number" for D6+)
                        if !excl_min.is_number() {
                            return Err(format!("{} is not of type \"number\"", value_to_string(excl_min)));
                        }
                    }
                }
            }
            if let Some(excl_max) = obj.get("exclusiveMaximum") {
                match draft {
                    Draft::D4 => {
                        if !excl_max.is_boolean() {
                            return Err(format!("{} is not of type \"boolean\"", value_to_string(excl_max)));
                        }
                    }
                    _ => {
                        if !excl_max.is_number() {
                            return Err(format!("{} is not of type \"number\"", value_to_string(excl_max)));
                        }
                    }
                }
            }
            // Check other simple keywords: if they exist, we assume valid for now
            // For nested schemas like properties, we should recursively validate?
            // For simplicity, we will not recursively validate inner schemas for meta-validation, only top-level.
            Ok(())
        }
        _ => Err("Schema must be object or boolean".to_string()),
    }
}

fn main() {
    // CLI parsing
    let mut cmd = Command::new("executable")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("SCHEMA").value_name("SCHEMA").help("The JSON Schema to validate with (i.e. schema.json)"))
        .arg(Arg::new("instance").short('i').long("instance").value_name("INSTANCES").help("A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)").action(clap::ArgAction::Append))
        .arg(Arg::new("draft").short('d').long("draft").value_name("DRAFT").help("Enforce a specific JSON Schema draft").value_parser(["4","6","7","2019","2020"]))
        .arg(Arg::new("assert-format").long("assert-format").help("Turn ON format validation").action(clap::ArgAction::SetTrue).conflicts_with("no-assert-format"))
        .arg(Arg::new("no-assert-format").long("no-assert-format").help("Turn OFF format validation").action(clap::ArgAction::SetTrue).conflicts_with("assert-format"))
        .arg(Arg::new("output").long("output").value_name("OUTPUT").help("Select output style: text (default), flag, list, hierarchical").default_value("text").value_parser(["text","flag","list","hierarchical"]))
        .arg(Arg::new("version").short('v').long("version").help("Show program's version number and exit").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("errors-only").long("errors-only").help("Only show validation errors").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("connect-timeout").long("connect-timeout").value_name("SECONDS").help("Timeout for establishing connections (in seconds)").value_parser(parse_seconds))
        .arg(Arg::new("timeout").long("timeout").value_name("SECONDS").help("Total timeout for HTTP requests (in seconds)").value_parser(parse_seconds))
        .arg(Arg::new("insecure").short('k').long("insecure").help("Skip TLS certificate verification (dangerous!)").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("cacert").long("cacert").value_name("FILE").help("Path to a custom CA certificate file (PEM format)"))
        .arg(Arg::new("help").short('h').long("help").help("Print help").action(clap::ArgAction::SetTrue));

    let matches = match cmd.clone().try_get_matches_from(std::env::args()) {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };

    if matches.get_flag("help") {
        println!("{}", cmd.render_help());
        return;
    }
    if matches.get_flag("version") {
        println!("Version: 0.41.0");
        return;
    }

    // Check cacert exists if provided
    if let Some(cacert_path) = matches.get_one::<String>("cacert") {
        match fs::read(cacert_path) {
            Ok(_) => {},
            Err(err) => {
                println!("Error: Failed to read certificate file '{}': {}", cacert_path, err);
                std::process::exit(1);
            }
        }
    }

    // Get schema path
    let schema_path_opt = matches.get_one::<String>("SCHEMA").cloned();
    let schema_path_str = match schema_path_opt {
        Some(s) => s,
        None => {
            // clap should have errored, but if not, we handle
            eprintln!("error: the following required arguments were not provided:\n  <SCHEMA>\n\nUsage: executable --instance <INSTANCES> <SCHEMA>\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    };

    // Read schema file
    let schema_content = match fs::read_to_string(&schema_path_str) {
        Ok(c) => c,
        Err(err) => {
            println!("Error: {}", err);
            std::process::exit(1);
        }
    };

    // Parse schema JSON
    let schema_json: Value = match serde_json::from_str(&schema_content) {
        Ok(v) => v,
        Err(err) => {
            println!("Error: {}", err);
            std::process::exit(1);
        }
    };

    // Determine draft
    let draft_opt_str = matches.get_one::<String>("draft").cloned();
    let mut draft = if let Some(d_str) = draft_opt_str {
        parse_draft_str(&d_str).unwrap_or(Draft::D2020)
    } else {
        // Detect from schema $schema
        if let Some(obj) = schema_json.as_object() {
            if let Some(sch) = obj.get("$schema") {
                if let Some(s_str) = sch.as_str() {
                    detect_draft_from_schema_str(s_str).unwrap_or(Draft::D2020)
                } else {
                    Draft::D2020
                }
            } else {
                Draft::D2020
            }
        } else {
            Draft::D2020
        }
    };

    // Determine assert-format
    let assert_format = if matches.get_flag("assert-format") {
        true
    } else if matches.get_flag("no-assert-format") {
        false
    } else {
        false // default OFF
    };

    // Determine output style
    let output_style = matches.get_one::<String>("output").unwrap().clone();
    let errors_only = matches.get_flag("errors-only");

    // Determine schema_id_base for schemaLocation
    // If schema has $id, use that $id + "#"
    // Else, use file:// absolute path + "#"
    let schema_id_base = {
        if let Some(obj) = schema_json.as_object() {
            if let Some(id_val) = obj.get("$id") {
                if let Some(id_str) = id_val.as_str() {
                    // Ensure ends with #? Original for $id case had # at end for root: e.g., https://example.com/my-schema#
                    // If id already contains #, keep, else add #
                    if id_str.ends_with('#') {
                        id_str.to_string()
                    } else {
                        format!("{}#", id_str)
                    }
                } else {
                    // Fallback to file uri
                    let abs_path = Path::new(&schema_path_str).canonicalize().unwrap_or_else(|_| PathBuf::from(&schema_path_str));
                    format!("file://{}#", abs_path.display())
                }
            } else {
                let abs_path = Path::new(&schema_path_str).canonicalize().unwrap_or_else(|_| PathBuf::from(&schema_path_str));
                format!("file://{}#", abs_path.display())
            }
        } else {
            let abs_path = Path::new(&schema_path_str).canonicalize().unwrap_or_else(|_| PathBuf::from(&schema_path_str));
            format!("file://{}#", abs_path.display())
        }
    };

    // Base dir for $ref resolution
    let base_dir = Path::new(&schema_path_str).parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));

    // Validate schema meta (is schema itself valid?)
    let schema_meta_valid = is_valid_schema_meta(&schema_json, &draft);
    let schema_is_valid = schema_meta_valid.is_ok();

    // If schema invalid, handle output and exit 1
    if !schema_is_valid {
        let err_msg = schema_meta_valid.err().unwrap();
        match output_style.as_str() {
            "text" => {
                println!("Schema is invalid. Error: {}", err_msg);
                std::process::exit(1);
            }
            "flag" => {
                // For flag output with schema only invalid, original printed JSON with valid false
                let obj = json!({
                    "output": "flag",
                    "payload": {"valid": false},
                    "schema": schema_path_str
                });
                println!("{}", obj);
                std::process::exit(1);
            }
            "list" => {
                // For simplicity, produce a payload with valid false and one detail? But original had huge meta details.
                // We'll produce simple list with root valid false
                // For schema meta invalid, we could attempt to produce a minimal list that still has valid false.
                // To be more compatible, we will produce a structure with root and maybe one child for the error? But we need schemaLocation for meta? For meta invalid, original's list had schemaLocation https://json-schema.org/draft/2020-12/schema# etc.
                // For simplicity, we'll produce payload valid false and details containing root and maybe error?
                // However, we need to match original's exit code 1.
                // We'll produce:
                // {"output":"list","payload":{"details":[{"evaluationPath":"","instanceLocation":"","schemaLocation":"<meta>","valid":false}],"valid":false},"schema":...}
                // But we don't have meta details.

                // For now, produce simple.
                let payload = json!({
                    "details": [
                        {
                            "evaluationPath": "",
                            "instanceLocation": "",
                            "schemaLocation": schema_id_base,
                            "valid": false
                        }
                    ],
                    "valid": false
                });
                let obj = json!({
                    "output": "list",
                    "payload": payload,
                    "schema": schema_path_str
                });
                println!("{}", obj);
                std::process::exit(1);
            }
            "hierarchical" => {
                let payload = json!({
                    "evaluationPath": "",
                    "instanceLocation": "",
                    "schemaLocation": schema_id_base,
                    "valid": false
                });
                let obj = json!({
                    "output": "hierarchical",
                    "payload": payload,
                    "schema": schema_path_str
                });
                println!("{}", obj);
                std::process::exit(1);
            }
            _ => {
                println!("Schema is invalid. Error: {}", err_msg);
                std::process::exit(1);
            }
        }
    }

    // Schema is valid
    let instances: Vec<String> = matches.get_many::<String>("instance").map(|v| v.cloned().collect()).unwrap_or_default();

    if instances.is_empty() {
        // No instances, just schema validation
        match output_style.as_str() {
            "text" => {
                if !errors_only {
                    println!("Schema is valid");
                }
                std::process::exit(0);
            }
            "flag" => {
                if errors_only {
                    // When errors_only and schema valid, original produced no output (empty)
                    std::process::exit(0);
                } else {
                    let obj = json!({
                        "output": "flag",
                        "payload": {"valid": true},
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                    std::process::exit(0);
                }
            }
            "list" => {
                if errors_only {
                    std::process::exit(0);
                } else {
                    // For schema only valid, original produced huge list from meta validation. We will produce simple.
                    let payload = json!({
                        "details": [
                            {
                                "evaluationPath": "",
                                "instanceLocation": "",
                                "schemaLocation": schema_id_base,
                                "valid": true
                            }
                        ],
                        "valid": true
                    });
                    let obj = json!({
                        "output": "list",
                        "payload": payload,
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                    std::process::exit(0);
                }
            }
            "hierarchical" => {
                if errors_only {
                    std::process::exit(0);
                } else {
                    let payload = json!({
                        "evaluationPath": "",
                        "instanceLocation": "",
                        "schemaLocation": schema_id_base,
                        "valid": true
                    });
                    let obj = json!({
                        "output": "hierarchical",
                        "payload": payload,
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                    std::process::exit(0);
                }
            }
            _ => {
                println!("Schema is valid");
                std::process::exit(0);
            }
        }
    } else {
        // Validate each instance
        let mut any_invalid = false;
        let mut overall_exit = 0;
        let ctx = ValidationContext {
            draft: draft.clone(),
            assert_format,
            schema_id_base: schema_id_base.clone(),
            base_dir: base_dir.clone(),
            root_schema: schema_json.clone(),
        };

        for inst_path in &instances {
            // Read instance file
            let inst_content = match fs::read_to_string(inst_path) {
                Ok(c) => c,
                Err(err) => {
                    // For file read error, original printed "Error: <err>" and exit 1, but also for multiple instances, it printed error for that instance and continued?
                    // Let's see earlier: with one valid and one missing, it printed valid for first, then error for second and exit 1.
                    // So we should print error and continue, but mark invalid.
                    match output_style.as_str() {
                        "text" => {
                            println!("Error: {}", err);
                        }
                        "flag" | "list" | "hierarchical" => {
                            // Original for file not found with flag output printed "Error: ..." not JSON? Let's check earlier: for file not found with flag output, it printed "Error: No such file..." not JSON. So for file errors, output style is ignored, it just prints error.
                            println!("Error: {}", err);
                        }
                        _ => {
                            println!("Error: {}", err);
                        }
                    }
                    any_invalid = true;
                    overall_exit = 1;
                    continue;
                }
            };

            // Parse instance JSON
            let inst_json: Value = match serde_json::from_str(&inst_content) {
                Ok(v) => v,
                Err(err) => {
                    // Similar to file error
                    println!("Error: {}", err);
                    any_invalid = true;
                    overall_exit = 1;
                    continue;
                }
            };

            // Validate instance against schema
            let (root_node, err_messages) = validate_instance(&schema_json, &inst_json, "", "", &schema_id_base, &ctx);

            let is_valid = root_node.valid;
            if !is_valid {
                any_invalid = true;
                overall_exit = 1;
            }

            // Output handling
            match output_style.as_str() {
                "text" => {
                    if errors_only && is_valid {
                        // Skip valid when errors-only
                        continue;
                    }
                    if is_valid {
                        println!("{} - VALID", inst_path);
                    } else {
                        // INVALID with errors
                        println!("{} - INVALID. Errors:", inst_path);
                        for (i, msg) in err_messages.iter().enumerate() {
                            println!("{}. {}", i+1, msg);
                        }
                    }
                }
                "flag" => {
                    if errors_only && is_valid {
                        continue;
                    }
                    let obj = json!({
                        "instance": inst_path,
                        "output": "flag",
                        "payload": {"valid": is_valid},
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                }
                "list" => {
                    if errors_only && is_valid {
                        continue;
                    }
                    // Build payload as list flat
                    let payload = root_node.to_list_json(&schema_id_base);
                    let obj = json!({
                        "instance": inst_path,
                        "output": "list",
                        "payload": payload,
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                }
                "hierarchical" => {
                    if errors_only && is_valid {
                        continue;
                    }
                    let payload = root_node.to_payload_hierarchical();
                    let obj = json!({
                        "instance": inst_path,
                        "output": "hierarchical",
                        "payload": payload,
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                }
                _ => {}
            }
        }

        std::process::exit(overall_exit);
    }
}
