fn is_valid_email(s: &str) -> bool {
    if s.contains(' ') { return false; }
    let parts: Vec<&str> = s.split('@').collect();
    if parts.len() != 2 { return false; }
    let local = parts[0];
    let domain = parts[1];
    if local.is_empty() || domain.is_empty() { return false; }
    if !domain.contains('.') { return false; }
    true
}

fn is_valid_date_time(s: &str) -> bool {
    chrono::DateTime::parse_from_rfc3339(s).is_ok()
}

fn is_valid_date(s: &str) -> bool {
    chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d").is_ok()
}

fn is_valid_time(s: &str) -> bool {
    if chrono::NaiveTime::parse_from_str(s, "%H:%M:%S").is_ok() { return true; }
    if chrono::NaiveTime::parse_from_str(s, "%H:%M:%S%.f").is_ok() { return true; }
    let re = Regex::new(r"^\d{2}:\d{2}:\d{2}(\.\d+)?(Z|[+-]\d{2}:\d{2})?$").unwrap();
    re.is_match(s)
}

fn is_valid_uri(s: &str) -> bool {
    url::Url::parse(s).is_ok()
}

fn is_valid_uri_reference(s: &str) -> bool {
    if url::Url::parse(s).is_ok() { return true; }
    !s.contains(' ') && !s.is_empty()
}

fn is_valid_ipv4(s: &str) -> bool {
    Ipv4Addr::from_str(s).is_ok()
}

fn is_valid_ipv6(s: &str) -> bool {
