    if s.is_empty() || s.len() > 253 { return false; }
    if s.contains(' ') { return false; }
    let re = Regex::new(r"^(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$").unwrap();
