            re.is_match(value)
        },
        _ => true,
    }
}

#[derive(Debug, Clone)]
struct OutputNode {
    evaluation_path: String,
    instance_location: String,
    schema_location: String,
    valid: bool,
    errors: Option<BTreeMap<String, Value>>,
    annotations: Option<Value>,
    dropped_annotations: Option<Value>,
    details: Vec<OutputNode>,
}

impl OutputNode {
    fn to_list_payload(&self) -> Value {
        let mut list = Vec::new();
        self.collect_list(&mut list);
        let details: Vec<Value> = list.into_iter().map(|node| node.to_json_object()).collect();
        json!({
            "details": details,
            "valid": self.valid
        })
    }

    fn collect_list<'a>(&'a self, out: &mut Vec<&'a OutputNode>) {
        out.push(self);
        for child in &self.details {
            child.collect_list(out);
        }
    }

    fn to_json_object(&self) -> Value {
        let mut map = serde_json::Map::new();
        if let Some(errs) = &self.errors {
            let mut err_map = serde_json::Map::new();
            for (k, v) in errs {
                err_map.insert(k.clone(), v.clone());
            }
            map.insert("errors".to_string(), Value::Object(err_map));
        }
        if let Some(ann) = &self.annotations {
            map.insert("annotations".to_string(), ann.clone());
        }
        if let Some(dropped) = &self.dropped_annotations {
            map.insert("droppedAnnotations".to_string(), dropped.clone());
        }
        map.insert("evaluationPath".to_string(), Value::String(self.evaluation_path.clone()));
        map.insert("instanceLocation".to_string(), Value::String(self.instance_location.clone()));
        map.insert("schemaLocation".to_string(), Value::String(self.schema_location.clone()));
        map.insert("valid".to_string(), Value::Bool(self.valid));
        Value::Object(map)
    }

    fn to_hierarchical_json(&self) -> Value {
        let mut map = serde_json::Map::new();
        if !self.details.is_empty() {
            let details: Vec<Value> = self.details.iter().map(|d| d.to_hierarchical_json()).collect();
            map.insert("details".to_string(), Value::Array(details));
        }
        if let Some(errs) = &self.errors {
            let mut err_map = serde_json::Map::new();
            for (k, v) in errs {
                err_map.insert(k.clone(), v.clone());
            }
            map.insert("errors".to_string(), Value::Object(err_map));
        }
        if let Some(ann) = &self.annotations {
            map.insert("annotations".to_string(), ann.clone());
        }
        if let Some(dropped) = &self.dropped_annotations {
            map.insert("droppedAnnotations".to_string(), dropped.clone());
        }
        map.insert("evaluationPath".to_string(), Value::String(self.evaluation_path.clone()));
        map.insert("instanceLocation".to_string(), Value::String(self.instance_location.clone()));
        map.insert("schemaLocation".to_string(), Value::String(self.schema_location.clone()));
        map.insert("valid".to_string(), Value::Bool(self.valid));
        Value::Object(map)
    }
}

struct ValidationContext {
    draft: Draft,
    assert_format: bool,
    schema_id_base: String,
    base_dir: PathBuf,
    root_schema: Value,
}

fn resolve_json_pointer<'a>(root: &'a Value, pointer: &str) -> Option<&'a Value> {
    if pointer.is_empty() || pointer == "#" {
        return Some(root);
    }
    let mut p = pointer;
    if p.starts_with('#') {
        p = &p[1..];
    }
    let mut current = root;
    if p.is_empty() {
        return Some(current);
    }
    for token in p.split('/').skip(1) {
        let token = token.replace("~1", "/").replace("~0", "~");
        match current {
            Value::Object(map) => {
                current = map.get(&token)?;
            }
            Value::Array(arr) => {
                let idx: usize = token.parse().ok()?;
                current = arr.get(idx)?;
            }
            _ => return None,
        }
    }
    Some(current)
}

fn resolve_ref(schema: &Value, ctx: &ValidationContext, ref_str: &str) -> Option<(Value, String)> {
    if ref_str.starts_with('#') {
        if let Some(target) = resolve_json_pointer(&ctx.root_schema, ref_str) {
            return Some((target.clone(), ref_str.to_string()));
        }
        None
    } else {
        let (file_part, pointer_part) = if let Some(idx) = ref_str.find('#') {
            (&ref_str[..idx], &ref_str[idx..])
        } else {
            (ref_str, "")
        };
        let file_path = if Path::new(file_part).is_absolute() {
            PathBuf::from(file_part)
        } else {
            ctx.base_dir.join(file_part)
        };
        if let Ok(content) = fs::read_to_string(&file_path) {
            if let Ok(val) = serde_json::from_str::<Value>(&content) {
                if pointer_part.is_empty() {
                    return Some((val, file_path.to_string_lossy().to_string()));
                } else {
                    if let Some(target) = resolve_json_pointer(&val, pointer_part) {
                        return Some((target.clone(), format!("{}#{}", file_part, pointer_part)));
                    }
                }
            }
        }
        None
    }
}

fn is_type(value: &Value, expected: &str) -> bool {
    match expected {
        "null" => value.is_null(),
        "boolean" => value.is_boolean(),
        "object" => value.is_object(),
        "array" => value.is_array(),
        "number" => value.is_number(),
        "string" => value.is_string(),
        "integer" => {
            if value.is_i64() || value.is_u64() { true }
            else if let Some(n) = value.as_f64() { n.fract() == 0.0 }
            else { false }
        }
        _ => false,
    }
}

fn validate_schema_object(
    schema: &Value,
    instance: &Value,
    instance_path: &str,
    schema_path: &str,
    schema_id_base: &str,
    ctx: &ValidationContext,
    errors: &mut Vec<String>,
) -> OutputNode {
    let mut valid = true;
    let mut child_details = Vec::new();

    // Handle $ref
    if let Some(obj) = schema.as_object() {
        if let Some(ref_val) = obj.get("$ref") {
            if let Some(ref_str) = ref_val.as_str() {
                if let Some((resolved_schema, _)) = resolve_ref(schema, ctx, ref_str) {
                    let ref_schema_path = format!("{}/$ref", schema_path);
                    let base_without_hash = if schema_id_base.ends_with('#') {
                        &schema_id_base[..schema_id_base.len()-1]
                    } else {
                        schema_id_base
                    };
                    let ref_schema_location = if ref_str.starts_with('#') {
                        format!("{}{}", base_without_hash, ref_str)
                    } else {
                        if let Some(idx) = ref_str.find('#') {
                            let file_part = &ref_str[..idx];
                            let frag = &ref_str[idx..];
                            let abs_path = ctx.base_dir.join(file_part);
                            let abs = abs_path.canonicalize().unwrap_or(abs_path);
                            format!("file://{}{}", abs.display(), frag)
                        } else {
                            let abs_path = ctx.base_dir.join(ref_str);
                            let abs = abs_path.canonicalize().unwrap_or(abs_path);
                            format!("file://{}#", abs.display())
                        }
                    };
                    let mut sub_ctx = ValidationContext {
                        draft: ctx.draft.clone(),
                        assert_format: ctx.assert_format,
                        schema_id_base: ref_schema_location.clone(),
                        base_dir: ctx.base_dir.clone(),
                        root_schema: ctx.root_schema.clone(),
                    };
                    if !ref_str.starts_with('#') {
                        let file_part = if let Some(idx) = ref_str.find('#') { &ref_str[..idx] } else { ref_str };
                        let file_path = if Path::new(file_part).is_absolute() {
                            PathBuf::from(file_part)
                        } else {
                            ctx.base_dir.join(file_part)
                        };
                        if let Some(parent) = file_path.parent() {
                            sub_ctx.base_dir = parent.to_path_buf();
                        }
                    }
                    let mut sub_errors = Vec::new();
                    let sub_node = validate_schema_object(
                        &resolved_schema,
                        instance,
                        instance_path,
                        &ref_schema_path,
                        &ref_schema_location,
                        &sub_ctx,
                        &mut sub_errors,
                    );
                    if !sub_node.valid {
                        valid = false;
                    }
                    errors.extend(sub_errors);
                    child_details.push(sub_node);
                } else {
                    valid = false;
                    let msg = format!("Failed to resolve $ref {}", ref_str);
                    errors.push(msg);
                }
            }
        }
    }

    if let Some(obj) = schema.as_object() {
        // type
        if let Some(type_val) = obj.get("type") {
            let eval_path = format!("{}/type", schema_path);
            let schema_loc = format!("{}{}", schema_id_base, "/type");
            let mut type_valid = true;
            let mut err_map = None;
            match type_val {
                Value::String(s) => {
                    if !is_type(instance, s) {
                        type_valid = false;
                        let inst_str = value_to_string(instance);
                        let msg = format!("{} is not of type \"{}\"", inst_str, s);
                        let mut map = BTreeMap::new();
                        map.insert("type".to_string(), Value::String(msg.clone()));
                        err_map = Some(map);
                        errors.push(msg);
                    }
                }
                Value::Array(arr) => {
                    let mut found = false;
                    let mut allowed = Vec::new();
                    for t in arr {
                        if let Some(s) = t.as_str() {
                            allowed.push(s.to_string());
                            if is_type(instance, s) { found = true; }
                        }
                    }
                    if !found {
                        type_valid = false;
                        let inst_str = value_to_string(instance);
                        let types_str = allowed.iter().map(|t| format!("\"{}\"", t)).collect::<Vec<_>>().join(", ");
                        let msg = if allowed.len() == 1 {
                            format!("{} is not of type {}", inst_str, types_str)
                        } else {
                            format!("{} is not of types {}", inst_str, types_str)
                        };
                        let mut map = BTreeMap::new();
                        map.insert("type".to_string(), Value::String(msg.clone()));
                        err_map = Some(map);
                        errors.push(msg);
                    }
                }
                _ => {}
            }
            let child = OutputNode {
                evaluation_path: eval_path,
                instance_location: instance_path.to_string(),
                schema_location: schema_loc,
                valid: type_valid,
                errors: err_map,
                annotations: None,
                dropped_annotations: None,
                details: Vec::new(),
            };
            if !type_valid { valid = false; }
            child_details.push(child);
        }

        // enum
        if let Some(enum_val) = obj.get("enum") {
            if let Some(arr) = enum_val.as_array() {
                let eval_path = format!("{}/enum", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/enum");
                let mut found = false;
                for v in arr {
                    if v == instance { found = true; break; }
                }
                let mut enum_valid = true;
                let mut err_map = None;
                if !found {
                    enum_valid = false;
                    valid = false;
                    let inst_str = value_to_string(instance);
                    let final_msg = if arr.len() <= 3 {
                        let items: Vec<String> = arr.iter().map(|v| value_to_string(v)).collect();
                        let list_str = if items.len() == 1 {
                            items[0].clone()
                        } else if items.len() == 2 {
                            format!("{} or {}", items[0], items[1])
                        } else {
                            format!("{}, {} or {}", items[0], items[1], items[2])
                        };
                        format!("{} is not one of {}", inst_str, list_str)
                    } else {
                        let first = value_to_string(&arr[0]);
                        let second = value_to_string(&arr[1]);
                        let remaining = arr.len() - 2;
                        format!("{} is not one of {}, {} or {} other candidates", inst_str, first, second, remaining)
                    };
                    let mut map = BTreeMap::new();
                    map.insert("enum".to_string(), Value::String(final_msg.clone()));
                    err_map = Some(map);
                    errors.push(final_msg);
                }
                let child = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: enum_valid,
                    errors: err_map,
                    annotations: None,
                    dropped_annotations: None,
                    details: Vec::new(),
                };
                child_details.push(child);
            }
        }

        // const
        if let Some(const_val) = obj.get("const") {
            let eval_path = format!("{}/const", schema_path);
            let schema_loc = format!("{}{}", schema_id_base, "/const");
            let mut const_valid = true;
            let mut err_map = None;
            if const_val != instance {
                const_valid = false;
                valid = false;
                let expected_str = value_to_string(const_val);
                let msg = format!("{} was expected", expected_str);
                let mut map = BTreeMap::new();
                map.insert("const".to_string(), Value::String(msg.clone()));
                err_map = Some(map);
                errors.push(msg);
            }
            let child = OutputNode {
                evaluation_path: eval_path,
                instance_location: instance_path.to_string(),
                schema_location: schema_loc,
                valid: const_valid,
                errors: err_map,
                annotations: None,
                dropped_annotations: None,
                details: Vec::new(),
            };
            child_details.push(child);
        }

        // multipleOf
        if let Some(mof) = obj.get("multipleOf") {
            if let Some(n) = mof.as_f64() {
                if let Some(inst_n) = instance.as_f64() {
                    let eval_path = format!("{}/multipleOf", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/multipleOf");
                    let mut mult_valid = true;
                    let mut err_map = None;
                    let remainder = if n != 0.0 { inst_n % n } else { 1.0 };
                    let is_multiple = remainder.abs() < 1e-10 || (n - remainder).abs() < 1e-10;
                    if !is_multiple {
                        mult_valid = false;
                        valid = false;
                        let inst_str = value_to_string(instance);
                        let msg = format!("{} is not a multiple of {}", inst_str, value_to_string(mof));
                        let mut map = BTreeMap::new();
                        map.insert("multipleOf".to_string(), Value::String(msg.clone()));
                        err_map = Some(map);
                        errors.push(msg);
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: mult_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        // minimum, maximum, exclusiveMinimum, exclusiveMaximum
        fn get_number(v: &Value) -> Option<f64> { v.as_f64() }

        if let Some(min_val) = obj.get("minimum") {
            if let Some(min_num) = get_number(min_val) {
                if let Some(inst_num) = get_number(instance) {
                    let eval_path = format!("{}/minimum", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/minimum");
                    let mut min_valid = true;
                    let mut err_map = None;
                    let exclusive = match ctx.draft {
                        Draft::D4 => {
                            if let Some(excl) = obj.get("exclusiveMinimum") {
                                excl.as_bool().unwrap_or(false)
                            } else { false }
                        }
                        _ => false
                    };
                    if exclusive {
                        if inst_num <= min_num {
                            min_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} is less than or equal to the minimum of {}", inst_str, value_to_string(min_val));
                            let mut map = BTreeMap::new();
                            map.insert("minimum".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                    } else {
                        if inst_num < min_num {
                            min_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} is less than the minimum of {}", inst_str, value_to_string(min_val));
                            let mut map = BTreeMap::new();
                            map.insert("minimum".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: min_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(max_val) = obj.get("maximum") {
            if let Some(max_num) = get_number(max_val) {
                if let Some(inst_num) = get_number(instance) {
                    let eval_path = format!("{}/maximum", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/maximum");
                    let mut max_valid = true;
                    let mut err_map = None;
                    let exclusive = match ctx.draft {
                        Draft::D4 => {
                            if let Some(excl) = obj.get("exclusiveMaximum") {
                                excl.as_bool().unwrap_or(false)
                            } else { false }
                        }
                        _ => false
                    };
                    if exclusive {
                        if inst_num >= max_num {
                            max_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} is greater than or equal to the maximum of {}", inst_str, value_to_string(max_val));
                            let mut map = BTreeMap::new();
                            map.insert("maximum".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                    } else {
                        if inst_num > max_num {
                            max_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} is greater than the maximum of {}", inst_str, value_to_string(max_val));
                            let mut map = BTreeMap::new();
                            map.insert("maximum".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: max_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(excl_min) = obj.get("exclusiveMinimum") {
            if let Some(excl_num) = get_number(excl_min) {
                if !matches!(ctx.draft, Draft::D4) {
                    if let Some(inst_num) = get_number(instance) {
                        let eval_path = format!("{}/exclusiveMinimum", schema_path);
                        let schema_loc = format!("{}{}", schema_id_base, "/exclusiveMinimum");
                        let mut excl_valid = true;
                        let mut err_map = None;
                        if inst_num <= excl_num {
                            excl_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} is less than or equal to the minimum of {}", inst_str, value_to_string(excl_min));
                            let mut map = BTreeMap::new();
                            map.insert("exclusiveMinimum".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                        let child = OutputNode {
                            evaluation_path: eval_path,
                            instance_location: instance_path.to_string(),
                            schema_location: schema_loc,
                            valid: excl_valid,
                            errors: err_map,
                            annotations: None,
                            dropped_annotations: None,
                            details: Vec::new(),
                        };
                        child_details.push(child);
                    }
                }
            }
        }

        if let Some(excl_max) = obj.get("exclusiveMaximum") {
            if let Some(excl_num) = get_number(excl_max) {
                if !matches!(ctx.draft, Draft::D4) {
                    if let Some(inst_num) = get_number(instance) {
                        let eval_path = format!("{}/exclusiveMaximum", schema_path);
                        let schema_loc = format!("{}{}", schema_id_base, "/exclusiveMaximum");
                        let mut excl_valid = true;
                        let mut err_map = None;
                        if inst_num >= excl_num {
                            excl_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} is greater than or equal to the maximum of {}", inst_str, value_to_string(excl_max));
                            let mut map = BTreeMap::new();
                            map.insert("exclusiveMaximum".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                        let child = OutputNode {
                            evaluation_path: eval_path,
                            instance_location: instance_path.to_string(),
                            schema_location: schema_loc,
                            valid: excl_valid,
                            errors: err_map,
                            annotations: None,
                            dropped_annotations: None,
                            details: Vec::new(),
                        };
                        child_details.push(child);
                    }
                }
            }
        }

        if let Some(min_len_val) = obj.get("minLength") {
            if let Some(min_len) = min_len_val.as_u64() {
                if let Some(s) = instance.as_str() {
                    let eval_path = format!("{}/minLength", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/minLength");
                    let mut len_valid = true;
                    let mut err_map = None;
                    if (s.chars().count() as u64) < min_len {
                        len_valid = false;
                        valid = false;
                        let inst_str = value_to_string(instance);
                        let msg = format!("{} is shorter than {} characters", inst_str, min_len);
                        let mut map = BTreeMap::new();
                        map.insert("minLength".to_string(), Value::String(msg.clone()));
                        err_map = Some(map);
                        errors.push(msg);
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: len_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(max_len_val) = obj.get("maxLength") {
            if let Some(max_len) = max_len_val.as_u64() {
                if let Some(s) = instance.as_str() {
                    let eval_path = format!("{}/maxLength", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/maxLength");
                    let mut len_valid = true;
                    let mut err_map = None;
                    if (s.chars().count() as u64) > max_len {
                        len_valid = false;
                        valid = false;
                        let inst_str = value_to_string(instance);
                        let msg = format!("{} is longer than {} characters", inst_str, max_len);
                        let mut map = BTreeMap::new();
                        map.insert("maxLength".to_string(), Value::String(msg.clone()));
                        err_map = Some(map);
                        errors.push(msg);
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: len_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(pattern_val) = obj.get("pattern") {
            if let Some(pattern_str) = pattern_val.as_str() {
                if let Some(s) = instance.as_str() {
                    let eval_path = format!("{}/pattern", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/pattern");
                    let mut pat_valid = true;
                    let mut err_map = None;
                    if let Ok(re) = Regex::new(pattern_str) {
                        if !re.is_match(s) {
                            pat_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} does not match \"{}\"", inst_str, pattern_str);
                            let mut map = BTreeMap::new();
                            map.insert("pattern".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: pat_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(min_items_val) = obj.get("minItems") {
            if let Some(min_items) = min_items_val.as_u64() {
                if let Some(arr) = instance.as_array() {
                    let eval_path = format!("{}/minItems", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/minItems");
                    let mut items_valid = true;
                    let mut err_map = None;
                    if (arr.len() as u64) < min_items {
                        items_valid = false;
                        valid = false;
                        let inst_str = value_to_string(instance);
                        let msg = format!("{} has less than {} items", inst_str, min_items);
                        let mut map = BTreeMap::new();
                        map.insert("minItems".to_string(), Value::String(msg.clone()));
                        err_map = Some(map);
                        errors.push(msg);
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: items_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(max_items_val) = obj.get("maxItems") {
            if let Some(max_items) = max_items_val.as_u64() {
                if let Some(arr) = instance.as_array() {
                    let eval_path = format!("{}/maxItems", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/maxItems");
                    let mut items_valid = true;
                    let mut err_map = None;
                    if (arr.len() as u64) > max_items {
                        items_valid = false;
                        valid = false;
                        let inst_str = value_to_string(instance);
                        let msg = format!("{} has more than {} items", inst_str, max_items);
                        let mut map = BTreeMap::new();
                        map.insert("maxItems".to_string(), Value::String(msg.clone()));
                        err_map = Some(map);
                        errors.push(msg);
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: items_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(unique_val) = obj.get("uniqueItems") {
            if let Some(b) = unique_val.as_bool() {
                if b {
                    if let Some(arr) = instance.as_array() {
                        let eval_path = format!("{}/uniqueItems", schema_path);
                        let schema_loc = format!("{}{}", schema_id_base, "/uniqueItems");
                        let mut uniq_valid = true;
                        let mut err_map = None;
                        let mut seen = HashSet::new();
                        let mut dup = false;
                        for item in arr {
                            let s = value_to_string(item);
                            if !seen.insert(s) { dup = true; break; }
                        }
                        if dup {
                            uniq_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} has non-unique elements", inst_str);
                            let mut map = BTreeMap::new();
                            map.insert("uniqueItems".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                        let child = OutputNode {
                            evaluation_path: eval_path,
                            instance_location: instance_path.to_string(),
                            schema_location: schema_loc,
                            valid: uniq_valid,
                            errors: err_map,
                            annotations: None,
                            dropped_annotations: None,
                            details: Vec::new(),
                        };
                        child_details.push(child);
                    }
                }
            }
        }

        if let Some(min_prop_val) = obj.get("minProperties") {
            if let Some(min_prop) = min_prop_val.as_u64() {
                if let Some(map) = instance.as_object() {
                    let eval_path = format!("{}/minProperties", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/minProperties");
                    let mut prop_valid = true;
                    let mut err_map = None;
                    if (map.len() as u64) < min_prop {
                        prop_valid = false;
                        valid = false;
                        let inst_str = value_to_string(instance);
                        let msg = format!("{} has less than {} properties", inst_str, min_prop);
                        let mut m = BTreeMap::new();
                        m.insert("minProperties".to_string(), Value::String(msg.clone()));
                        err_map = Some(m);
                        errors.push(msg);
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: prop_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(max_prop_val) = obj.get("maxProperties") {
            if let Some(max_prop) = max_prop_val.as_u64() {
                if let Some(map) = instance.as_object() {
                    let eval_path = format!("{}/maxProperties", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/maxProperties");
                    let mut prop_valid = true;
                    let mut err_map = None;
                    if (map.len() as u64) > max_prop {
                        prop_valid = false;
                        valid = false;
                        let inst_str = value_to_string(instance);
                        let msg = format!("{} has more than {} properties", inst_str, max_prop);
                        let mut m = BTreeMap::new();
                        m.insert("maxProperties".to_string(), Value::String(msg.clone()));
                        err_map = Some(m);
                        errors.push(msg);
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: prop_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(req_val) = obj.get("required") {
            if let Some(req_arr) = req_val.as_array() {
                if let Some(inst_map) = instance.as_object() {
                    let eval_path = format!("{}/required", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/required");
                    let mut req_valid = true;
                    let mut missing = Vec::new();
                    for req in req_arr {
                        if let Some(prop) = req.as_str() {
                            if !inst_map.contains_key(prop) { missing.push(prop.to_string()); }
                        }
                    }
                    let mut err_map = None;
                    if !missing.is_empty() {
                        req_valid = false;
                        valid = false;
                        let mut msgs = Vec::new();
                        for m in &missing {
                            msgs.push(format!("\"{}\" is a required property", m));
                        }
                        let err_value = if msgs.len() == 1 {
                            Value::String(msgs[0].clone())
                        } else {
                            Value::Array(msgs.iter().map(|s| Value::String(s.clone())).collect())
                        };
                        let mut map = BTreeMap::new();
                        map.insert("required".to_string(), err_value);
                        err_map = Some(map);
                        for msg in msgs { errors.push(msg); }
                    }
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: req_valid,
                        errors: err_map,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(add_prop) = obj.get("additionalProperties") {
            if let Some(inst_map) = instance.as_object() {
                let eval_path = format!("{}/additionalProperties", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/additionalProperties");
                let mut allowed = HashSet::new();
                if let Some(props) = obj.get("properties") {
                    if let Some(pmap) = props.as_object() {
                        for k in pmap.keys() { allowed.insert(k.clone()); }
                    }
                }
                let mut pattern_props = Vec::new();
                if let Some(pat_props) = obj.get("patternProperties") {
                    if let Some(pmap) = pat_props.as_object() {
                        for (pat, _) in pmap {
                            if let Ok(re) = Regex::new(pat) { pattern_props.push(re); }
                        }
                    }
                }
                let mut unexpected = Vec::new();
                for prop in inst_map.keys() {
                    if allowed.contains(prop) { continue; }
                    let mut matched = false;
                    for re in &pattern_props {
                        if re.is_match(prop) { matched = true; break; }
                    }
                    if matched { continue; }
                    unexpected.push(prop.clone());
                }
                if !unexpected.is_empty() {
                    match add_prop {
                        Value::Bool(b) => {
                            if !b {
                                let mut err_map = None;
                                let msg = if unexpected.len() == 1 {
                                    format!("Additional properties are not allowed ('{}' was unexpected)", unexpected[0])
                                } else {
                                    let quoted: Vec<String> = unexpected.iter().map(|p| format!("'{}'", p)).collect();
                                    format!("Additional properties are not allowed ({} were unexpected)", quoted.join(", "))
                                };
                                let mut map = BTreeMap::new();
                                map.insert("additionalProperties".to_string(), Value::String(msg.clone()));
                                err_map = Some(map);
                                errors.push(msg);
                                let child = OutputNode {
                                    evaluation_path: eval_path,
                                    instance_location: instance_path.to_string(),
                                    schema_location: schema_loc,
                                    valid: false,
                                    errors: err_map,
                                    annotations: None,
                                    dropped_annotations: None,
                                    details: Vec::new(),
                                };
                                valid = false;
                                child_details.push(child);
                            } else {
                                let child = OutputNode {
                                    evaluation_path: eval_path,
                                    instance_location: instance_path.to_string(),
                                    schema_location: schema_loc,
                                    valid: true,
                                    errors: None,
                                    annotations: None,
                                    dropped_annotations: None,
                                    details: Vec::new(),
                                };
                                child_details.push(child);
                            }
                        }
                        Value::Object(_) | Value::Bool(_) => {
                            // For schema case, validate each unexpected prop
                            let mut all_valid = true;
                            let mut details = Vec::new();
                            for prop in &unexpected {
                                if let Some(prop_val) = inst_map.get(prop) {
                                    let mut sub_errors = Vec::new();
                                    let sub_schema_path = format!("{}/additionalProperties", schema_path);
                                    let sub_schema_loc = format!("{}{}", schema_id_base, "/additionalProperties");
                                    let sub_inst_path = format!("{}/{}", instance_path, json_pointer_escape(prop));
                                    let sub_node = validate_schema_object(
                                        add_prop,
                                        prop_val,
                                        &sub_inst_path,
                                        &sub_schema_path,
                                        &sub_schema_loc,
                                        ctx,
                                        &mut sub_errors,
                                    );
                                    if !sub_node.valid { all_valid = false; valid = false; }
                                    errors.extend(sub_errors);
                                    details.push(sub_node);
                                }
                            }
                            let child = OutputNode {
                                evaluation_path: eval_path,
                                instance_location: instance_path.to_string(),
                                schema_location: schema_loc,
                                valid: all_valid,
                                errors: None,
                                annotations: None,
                                dropped_annotations: None,
                                details,
                            };
                            child_details.push(child);
                        }
                        _ => {}
                    }
                } else {
                    // No unexpected, valid
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: true,
                        errors: None,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(props) = obj.get("properties") {
            if let Some(props_map) = props.as_object() {
                if let Some(inst_map) = instance.as_object() {
                    let eval_path = format!("{}/properties", schema_path);
                    let schema_loc = format!("{}{}", schema_id_base, "/properties");
                    let mut props_valid = true;
                    let mut props_details = Vec::new();
                    let mut annotations = Vec::new();
                    let mut dropped = Vec::new();
                    let mut sorted_keys: Vec<&String> = props_map.keys().collect();
                    sorted_keys.sort();
                    for prop_name in sorted_keys {
                        let prop_schema = &props_map[prop_name];
                        let child_inst_path = format!("{}/{}", instance_path, json_pointer_escape(prop_name));
                        let child_schema_path = format!("{}/properties/{}", schema_path, json_pointer_escape(prop_name));
                        let child_schema_loc = format!("{}/properties/{}", schema_id_base, json_pointer_escape(prop_name));
                        if let Some(inst_val) = inst_map.get(prop_name) {
                            let mut sub_errors = Vec::new();
                            let sub_node = validate_schema_object(
                                prop_schema,
                                inst_val,
                                &child_inst_path,
                                &child_schema_path,
                                &child_schema_loc,
                                ctx,
                                &mut sub_errors,
                            );
                            if !sub_node.valid {
                                props_valid = false;
                                valid = false;
                                dropped.push(prop_name.clone());
                            } else {
                                annotations.push(prop_name.clone());
                            }
                            errors.extend(sub_errors);
                            props_details.push(sub_node);
                        }
                    }
                    let (ann_val, drop_val) = if props_valid {
                        (Some(Value::Array(annotations.iter().map(|s| Value::String(s.clone())).collect())), None)
                    } else {
                        (None, Some(Value::Array(dropped.iter().map(|s| Value::String(s.clone())).collect())))
                    };
                    let props_node = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: props_valid,
                        errors: None,
                        annotations: ann_val,
                        dropped_annotations: drop_val,
                        details: props_details,
                    };
                    child_details.push(props_node);
                }
            }
        }

        if let Some(items_schema) = obj.get("items") {
            if let Some(arr) = instance.as_array() {
                let eval_path = format!("{}/items", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/items");
                let mut items_valid = true;
                let mut items_details = Vec::new();
                match items_schema {
                    Value::Object(_) | Value::Bool(_) => {
                        for (idx, item) in arr.iter().enumerate() {
                            let child_inst_path = format!("{}/{}", instance_path, idx);
                            let child_schema_path = format!("{}/items", schema_path);
                            let child_schema_loc = format!("{}{}", schema_id_base, "/items");
                            let mut sub_errors = Vec::new();
                            let sub_node = validate_schema_object(
                                items_schema,
                                item,
                                &child_inst_path,
                                &child_schema_path,
                                &child_schema_loc,
                                ctx,
                                &mut sub_errors,
                            );
                            if !sub_node.valid { items_valid = false; valid = false; }
                            errors.extend(sub_errors);
                            items_details.push(sub_node);
                        }
                    }
                    Value::Array(schemas) => {
                        for (idx, (item, item_schema)) in arr.iter().zip(schemas.iter()).enumerate() {
                            let child_inst_path = format!("{}/{}", instance_path, idx);
                            let child_schema_path = format!("{}/items/{}", schema_path, idx);
                            let child_schema_loc = format!("{}/items/{}", schema_id_base, idx);
                            let mut sub_errors = Vec::new();
                            let sub_node = validate_schema_object(
                                item_schema,
                                item,
                                &child_inst_path,
                                &child_schema_path,
                                &child_schema_loc,
                                ctx,
                                &mut sub_errors,
                            );
                            if !sub_node.valid { items_valid = false; valid = false; }
                            errors.extend(sub_errors);
                            items_details.push(sub_node);
                        }
                    }
                    _ => {}
                }
                let items_node = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: items_valid,
                    errors: None,
                    annotations: None,
                    dropped_annotations: None,
                    details: items_details,
                };
                child_details.push(items_node);
            }
        }

        if let Some(any_of) = obj.get("anyOf") {
            if let Some(arr) = any_of.as_array() {
                let eval_path = format!("{}/anyOf", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/anyOf");
                let mut any_valid = false;
                let mut any_details = Vec::new();
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let child_schema_path = format!("{}/anyOf/{}", schema_path, idx);
                    let child_schema_loc = format!("{}/anyOf/{}", schema_id_base, idx);
                    let mut sub_errors = Vec::new();
                    let sub_node = validate_schema_object(
                        sub_schema,
                        instance,
                        instance_path,
                        &child_schema_path,
                        &child_schema_loc,
                        ctx,
                        &mut sub_errors,
                    );
                    if sub_node.valid { any_valid = true; }
                    any_details.push(sub_node);
                }
                if !any_valid {
                    valid = false;
                    let inst_str = value_to_string(instance);
                    let msg = format!("{} is not valid under any of the schemas listed in the 'anyOf' keyword", inst_str);
                    let child = OutputNode {
                        evaluation_path: eval_path.clone(),
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc.clone(),
                        valid: false,
                        errors: Some({
                            let mut m = BTreeMap::new();
                            m.insert("anyOf".to_string(), Value::String(msg.clone()));
                            m
                        }),
                        annotations: None,
                        dropped_annotations: None,
                        details: any_details,
                    };
                    child_details.push(child);
                    errors.push(msg);
                } else {
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: true,
                        errors: None,
                        annotations: None,
                        dropped_annotations: None,
                        details: any_details,
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(all_of) = obj.get("allOf") {
            if let Some(arr) = all_of.as_array() {
                let eval_path = format!("{}/allOf", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/allOf");
                let mut all_valid = true;
                let mut all_details = Vec::new();
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let child_schema_path = format!("{}/allOf/{}", schema_path, idx);
                    let child_schema_loc = format!("{}/allOf/{}", schema_id_base, idx);
                    let mut sub_errors = Vec::new();
                    let sub_node = validate_schema_object(
                        sub_schema,
                        instance,
                        instance_path,
                        &child_schema_path,
                        &child_schema_loc,
                        ctx,
                        &mut sub_errors,
                    );
                    if !sub_node.valid { all_valid = false; valid = false; }
                    errors.extend(sub_errors);
                    all_details.push(sub_node);
                }
                let child = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: all_valid,
                    errors: None,
                    annotations: None,
                    dropped_annotations: None,
                    details: all_details,
                };
                child_details.push(child);
            }
        }

        if let Some(one_of) = obj.get("oneOf") {
            if let Some(arr) = one_of.as_array() {
                let eval_path = format!("{}/oneOf", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/oneOf");
                let mut valid_count = 0;
                let mut one_details = Vec::new();
                for (idx, sub_schema) in arr.iter().enumerate() {
                    let child_schema_path = format!("{}/oneOf/{}", schema_path, idx);
                    let child_schema_loc = format!("{}/oneOf/{}", schema_id_base, idx);
                    let mut sub_errors = Vec::new();
                    let sub_node = validate_schema_object(
                        sub_schema,
                        instance,
                        instance_path,
                        &child_schema_path,
                        &child_schema_loc,
                        ctx,
                        &mut sub_errors,
                    );
                    if sub_node.valid { valid_count += 1; }
                    one_details.push(sub_node);
                }
                let one_valid = valid_count == 1;
                if !one_valid {
                    valid = false;
                    let inst_str = value_to_string(instance);
                    let msg = if valid_count == 0 {
                        format!("{} is not valid under any of the schemas listed in the 'oneOf' keyword", inst_str)
                    } else {
                        format!("{} is valid under more than one of the schemas listed in the 'oneOf' keyword", inst_str)
                    };
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: false,
                        errors: Some({
                            let mut m = BTreeMap::new();
                            m.insert("oneOf".to_string(), Value::String(msg.clone()));
                            m
                        }),
                        annotations: None,
                        dropped_annotations: None,
                        details: one_details,
                    };
                    child_details.push(child);
                    errors.push(msg);
                } else {
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: true,
                        errors: None,
                        annotations: None,
                        dropped_annotations: None,
                        details: one_details,
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(not_schema) = obj.get("not") {
            let eval_path = format!("{}/not", schema_path);
            let schema_loc = format!("{}{}", schema_id_base, "/not");
            let mut sub_errors = Vec::new();
            let sub_node = validate_schema_object(
                not_schema,
                instance,
                instance_path,
                &format!("{}/not", schema_path),
                &format!("{}{}", schema_id_base, "/not"),
                ctx,
                &mut sub_errors,
            );
            let not_valid = !sub_node.valid;
            if !not_valid {
                valid = false;
                let not_schema_str = value_to_string(not_schema);
                let inst_str = value_to_string(instance);
                let msg = format!("{} is not allowed for {}", not_schema_str, inst_str);
                let mut map = BTreeMap::new();
                map.insert("not".to_string(), Value::String(msg.clone()));
                let child = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: false,
                    errors: Some(map),
                    annotations: None,
                    dropped_annotations: None,
                    details: vec![sub_node],
                };
                child_details.push(child);
                errors.push(msg);
            } else {
                let child = OutputNode {
                    evaluation_path: eval_path,
                    instance_location: instance_path.to_string(),
                    schema_location: schema_loc,
                    valid: true,
                    errors: None,
                    annotations: None,
                    dropped_annotations: None,
                    details: vec![sub_node],
                };
                child_details.push(child);
            }
        }

        if let Some(contains_schema) = obj.get("contains") {
            if let Some(arr) = instance.as_array() {
                let eval_path = format!("{}/contains", schema_path);
                let schema_loc = format!("{}{}", schema_id_base, "/contains");
                let mut contains_valid = false;
                let mut contains_details = Vec::new();
                for (idx, item) in arr.iter().enumerate() {
                    let mut sub_errors = Vec::new();
                    let sub_node = validate_schema_object(
                        contains_schema,
                        item,
                        &format!("{}/{}", instance_path, idx),
                        &format!("{}/contains", schema_path),
                        &format!("{}{}", schema_id_base, "/contains"),
                        ctx,
                        &mut sub_errors,
                    );
                    if sub_node.valid { contains_valid = true; break; }
                    contains_details.push(sub_node);
                }
                if !contains_valid {
                    valid = false;
                    let inst_str = value_to_string(instance);
                    let msg = format!("None of {} are valid under the given schema", inst_str);
                    let mut map = BTreeMap::new();
                    map.insert("contains".to_string(), Value::String(msg.clone()));
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: false,
                        errors: Some(map),
                        annotations: None,
                        dropped_annotations: None,
                        details: contains_details,
                    };
                    child_details.push(child);
                    errors.push(msg);
                } else {
                    let child = OutputNode {
                        evaluation_path: eval_path,
                        instance_location: instance_path.to_string(),
                        schema_location: schema_loc,
                        valid: true,
                        errors: None,
                        annotations: None,
                        dropped_annotations: None,
                        details: Vec::new(),
                    };
                    child_details.push(child);
                }
            }
        }

        if let Some(format_val) = obj.get("format") {
            if let Some(fmt_str) = format_val.as_str() {
                if ctx.assert_format {
                    if let Some(s) = instance.as_str() {
                        let eval_path = format!("{}/format", schema_path);
                        let schema_loc = format!("{}{}", schema_id_base, "/format");
                        let mut fmt_valid = true;
                        let mut err_map = None;
                        if !is_valid_format(fmt_str, s) {
                            fmt_valid = false;
                            valid = false;
                            let inst_str = value_to_string(instance);
                            let msg = format!("{} is not a \"{}\"", inst_str, fmt_str);
                            let mut map = BTreeMap::new();
                            map.insert("format".to_string(), Value::String(msg.clone()));
                            err_map = Some(map);
                            errors.push(msg);
                        }
                        let child = OutputNode {
                            evaluation_path: eval_path,
                            instance_location: instance_path.to_string(),
                            schema_location: schema_loc,
                            valid: fmt_valid,
                            errors: err_map,
                            annotations: None,
                            dropped_annotations: None,
                            details: Vec::new(),
                        };
                        child_details.push(child);
                    }
                }
            }
        }
    }

    OutputNode {
        evaluation_path: schema_path.to_string(),
        instance_location: instance_path.to_string(),
        schema_location: schema_id_base.to_string(),
        valid,
        errors: None,
        annotations: None,
        dropped_annotations: None,
        details: child_details,
    }
}

fn validate_boolean_schema(
    schema_bool: bool,
    instance: &Value,
    instance_path: &str,
    schema_path: &str,
    schema_id_base: &str,
) -> (OutputNode, Vec<String>) {
    let mut errors = Vec::new();
    if schema_bool {
        let node = OutputNode {
            evaluation_path: schema_path.to_string(),
            instance_location: instance_path.to_string(),
            schema_location: schema_id_base.to_string(),
            valid: true,
            errors: None,
            annotations: None,
            dropped_annotations: None,
            details: Vec::new(),
        };
        (node, errors)
    } else {
        let inst_str = value_to_string(instance);
        let msg = format!("False schema does not allow {}", inst_str);
        errors.push(msg.clone());
        let mut err_map = BTreeMap::new();
        err_map.insert("falseSchema".to_string(), Value::String(msg));
        let node = OutputNode {
            evaluation_path: schema_path.to_string(),
            instance_location: instance_path.to_string(),
            schema_location: schema_id_base.to_string(),
            valid: false,
            errors: Some(err_map),
            annotations: None,
            dropped_annotations: None,
            details: Vec::new(),
        };
        (node, errors)
    }
}

fn validate_instance(
    schema: &Value,
    instance: &Value,
    instance_path: &str,
    schema_path: &str,
    schema_id_base: &str,
    ctx: &ValidationContext,
) -> (OutputNode, Vec<String>) {
    match schema {
        Value::Bool(b) => validate_boolean_schema(*b, instance, instance_path, schema_path, schema_id_base),
        Value::Object(_) => {
            let mut errors = Vec::new();
            let node = validate_schema_object(schema, instance, instance_path, schema_path, schema_id_base, ctx, &mut errors);
            (node, errors)
        }
        _ => {
            let node = OutputNode {
                evaluation_path: schema_path.to_string(),
                instance_location: instance_path.to_string(),
                schema_location: schema_id_base.to_string(),
                valid: true,
                errors: None,
                annotations: None,
                dropped_annotations: None,
                details: Vec::new(),
            };
            (node, Vec::new())
        }
    }
}

fn is_valid_schema_meta(schema: &Value, draft: &Draft) -> Result<(), String> {
    match schema {
        Value::Bool(_) => Ok(()),
        Value::Object(obj) => {
            if let Some(type_val) = obj.get("type") {
                match type_val {
                    Value::String(s) => {
                        let allowed = ["array","boolean","integer","null","number","object","string"];
                        if !allowed.contains(&s.as_str()) {
                            return Err(format!("\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword", s));
                        }
                    }
                    Value::Array(arr) => {
                        for item in arr {
                            if let Some(s) = item.as_str() {
                                let allowed = ["array","boolean","integer","null","number","object","string"];
                                if !allowed.contains(&s) {
                                    return Err(format!("\"{}\" is not valid under any of the schemas listed in the 'anyOf' keyword", s));
                                }
                            } else {
                                return Err("type array must contain strings".to_string());
                            }
                        }
                    }
                    _ => return Err("type must be string or array".to_string()),
                }
            }
            if let Some(excl_min) = obj.get("exclusiveMinimum") {
                match draft {
                    Draft::D4 => {
                        if !excl_min.is_boolean() {
                            return Err(format!("{} is not of type \"boolean\"", value_to_string(excl_min)));
                        }
                    }
                    _ => {
                        if !excl_min.is_number() {
                            return Err(format!("{} is not of type \"number\"", value_to_string(excl_min)));
                        }
                    }
                }
            }
            if let Some(excl_max) = obj.get("exclusiveMaximum") {
                match draft {
                    Draft::D4 => {
                        if !excl_max.is_boolean() {
                            return Err(format!("{} is not of type \"boolean\"", value_to_string(excl_max)));
                        }
                    }
                    _ => {
                        if !excl_max.is_number() {
                            return Err(format!("{} is not of type \"number\"", value_to_string(excl_max)));
                        }
                    }
                }
            }
            Ok(())
        }
        _ => Err("Schema must be object or boolean".to_string()),
    }
}

fn main() {
    let mut cmd = Command::new("executable")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("SCHEMA").value_name("SCHEMA").help("The JSON Schema to validate with (i.e. schema.json)"))
        .arg(Arg::new("instance").short('i').long("instance").value_name("INSTANCES").help("A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)").action(clap::ArgAction::Append))
        .arg(Arg::new("draft").short('d').long("draft").value_name("DRAFT").help("Enforce a specific JSON Schema draft").value_parser(["4","6","7","2019","2020"]))
        .arg(Arg::new("assert-format").long("assert-format").help("Turn ON format validation").action(clap::ArgAction::SetTrue).conflicts_with("no-assert-format"))
        .arg(Arg::new("no-assert-format").long("no-assert-format").help("Turn OFF format validation").action(clap::ArgAction::SetTrue).conflicts_with("assert-format"))
        .arg(Arg::new("output").long("output").value_name("OUTPUT").help("Select output style: text (default), flag, list, hierarchical").default_value("text").value_parser(["text","flag","list","hierarchical"]))
        .arg(Arg::new("version").short('v').long("version").help("Show program's version number and exit").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("errors-only").long("errors-only").help("Only show validation errors").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("connect-timeout").long("connect-timeout").value_name("SECONDS").help("Timeout for establishing connections (in seconds)").value_parser(parse_seconds))
        .arg(Arg::new("timeout").long("timeout").value_name("SECONDS").help("Total timeout for HTTP requests (in seconds)").value_parser(parse_seconds))
        .arg(Arg::new("insecure").short('k').long("insecure").help("Skip TLS certificate verification (dangerous!)").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("cacert").long("cacert").value_name("FILE").help("Path to a custom CA certificate file (PEM format)"))
        .arg(Arg::new("help").short('h').long("help").help("Print help").action(clap::ArgAction::SetTrue));

    let matches = match cmd.clone().try_get_matches_from(std::env::args()) {
        Ok(m) => m,
        Err(e) => { e.exit(); }
    };

    if matches.get_flag("help") {
        println!("{}", cmd.render_help());
        return;
    }
    if matches.get_flag("version") {
        println!("Version: 0.41.0");
        return;
    }

    if let Some(cacert_path) = matches.get_one::<String>("cacert") {
        match fs::read(cacert_path) {
            Ok(_) => {},
            Err(err) => {
                println!("Error: Failed to read certificate file '{}': {}", cacert_path, err);
                std::process::exit(1);
            }
        }
    }

    let schema_path_opt = matches.get_one::<String>("SCHEMA").cloned();
    let schema_path_str = match schema_path_opt {
        Some(s) => s,
        None => {
            eprintln!("error: the following required arguments were not provided:\n  <SCHEMA>\n\nUsage: executable --instance <INSTANCES> <SCHEMA>\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    };

    let schema_content = match fs::read_to_string(&schema_path_str) {
        Ok(c) => c,
        Err(err) => {
            println!("Error: {}", err);
            std::process::exit(1);
        }
    };

    let schema_json: Value = match serde_json::from_str(&schema_content) {
        Ok(v) => v,
        Err(err) => {
            println!("Error: {}", err);
            std::process::exit(1);
        }
    };

    let draft_opt_str = matches.get_one::<String>("draft").cloned();
    let draft = if let Some(d_str) = draft_opt_str {
        parse_draft_str(&d_str).unwrap_or(Draft::D2020)
    } else {
        if let Some(obj) = schema_json.as_object() {
            if let Some(sch) = obj.get("$schema") {
                if let Some(s_str) = sch.as_str() {
                    detect_draft_from_schema_str(s_str).unwrap_or(Draft::D2020)
                } else { Draft::D2020 }
            } else { Draft::D2020 }
        } else { Draft::D2020 }
    };

    let assert_format = if matches.get_flag("assert-format") { true } else if matches.get_flag("no-assert-format") { false } else { false };

    let output_style = matches.get_one::<String>("output").unwrap().clone();
    let errors_only = matches.get_flag("errors-only");

    let schema_id_base = {
        if let Some(obj) = schema_json.as_object() {
            if let Some(id_val) = obj.get("$id") {
                if let Some(id_str) = id_val.as_str() {
                    if id_str.ends_with('#') { id_str.to_string() } else { format!("{}#", id_str) }
                } else {
                    let abs_path = Path::new(&schema_path_str).canonicalize().unwrap_or_else(|_| PathBuf::from(&schema_path_str));
                    format!("file://{}#", abs_path.display())
                }
            } else {
                let abs_path = Path::new(&schema_path_str).canonicalize().unwrap_or_else(|_| PathBuf::from(&schema_path_str));
                format!("file://{}#", abs_path.display())
            }
        } else {
            let abs_path = Path::new(&schema_path_str).canonicalize().unwrap_or_else(|_| PathBuf::from(&schema_path_str));
            format!("file://{}#", abs_path.display())
        }
    };

    let base_dir = Path::new(&schema_path_str).parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."));

    let schema_meta_valid = is_valid_schema_meta(&schema_json, &draft);
    let schema_is_valid = schema_meta_valid.is_ok();

    if !schema_is_valid {
        let err_msg = schema_meta_valid.err().unwrap();
        match output_style.as_str() {
            "text" => {
                println!("Schema is invalid. Error: {}", err_msg);
                std::process::exit(1);
            }
            "flag" => {
                let obj = json!({
                    "output": "flag",
                    "payload": {"valid": false},
                    "schema": schema_path_str
                });
                println!("{}", obj);
                std::process::exit(1);
            }
            "list" => {
                let payload = json!({
                    "details": [
                        {
                            "evaluationPath": "",
                            "instanceLocation": "",
                            "schemaLocation": schema_id_base,
                            "valid": false
                        }
                    ],
                    "valid": false
                });
                let obj = json!({
                    "output": "list",
                    "payload": payload,
                    "schema": schema_path_str
                });
                println!("{}", obj);
                std::process::exit(1);
            }
            "hierarchical" => {
                let payload = json!({
                    "evaluationPath": "",
                    "instanceLocation": "",
                    "schemaLocation": schema_id_base,
                    "valid": false
                });
                let obj = json!({
                    "output": "hierarchical",
                    "payload": payload,
                    "schema": schema_path_str
                });
                println!("{}", obj);
                std::process::exit(1);
            }
            _ => {
                println!("Schema is invalid. Error: {}", err_msg);
                std::process::exit(1);
            }
        }
    }

    let instances: Vec<String> = matches.get_many::<String>("instance").map(|v| v.cloned().collect()).unwrap_or_default();

    if instances.is_empty() {
        match output_style.as_str() {
            "text" => {
                if !errors_only {
                    println!("Schema is valid");
                }
                std::process::exit(0);
            }
            "flag" => {
                if errors_only {
                    std::process::exit(0);
                } else {
                    let obj = json!({
                        "output": "flag",
                        "payload": {"valid": true},
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                    std::process::exit(0);
                }
            }
            "list" => {
                if errors_only {
                    std::process::exit(0);
                } else {
                    let payload = json!({
                        "details": [
                            {
                                "evaluationPath": "",
                                "instanceLocation": "",
                                "schemaLocation": schema_id_base,
                                "valid": true
                            }
                        ],
                        "valid": true
                    });
                    let obj = json!({
                        "output": "list",
                        "payload": payload,
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                    std::process::exit(0);
                }
            }
            "hierarchical" => {
                if errors_only {
                    std::process::exit(0);
                } else {
                    let payload = json!({
                        "evaluationPath": "",
                        "instanceLocation": "",
                        "schemaLocation": schema_id_base,
                        "valid": true
                    });
                    let obj = json!({
                        "output": "hierarchical",
                        "payload": payload,
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                    std::process::exit(0);
                }
            }
            _ => {
                println!("Schema is valid");
                std::process::exit(0);
            }
        }
    } else {
        let mut overall_exit = 0;
        let ctx = ValidationContext {
            draft,
            assert_format,
            schema_id_base: schema_id_base.clone(),
            base_dir,
            root_schema: schema_json.clone(),
        };

        for inst_path in &instances {
            let inst_content = match fs::read_to_string(inst_path) {
                Ok(c) => c,
                Err(err) => {
                    println!("Error: {}", err);
                    overall_exit = 1;
                    continue;
                }
            };
            let inst_json: Value = match serde_json::from_str(&inst_content) {
                Ok(v) => v,
                Err(err) => {
                    println!("Error: {}", err);
                    overall_exit = 1;
                    continue;
                }
            };
            let (root_node, err_messages) = validate_instance(&schema_json, &inst_json, "", "", &schema_id_base, &ctx);
            let is_valid = root_node.valid;
            if !is_valid { overall_exit = 1; }
            match output_style.as_str() {
                "text" => {
                    if errors_only && is_valid { continue; }
                    if is_valid {
                        println!("{} - VALID", inst_path);
                    } else {
                        println!("{} - INVALID. Errors:", inst_path);
                        for (i, msg) in err_messages.iter().enumerate() {
                            println!("{}. {}", i+1, msg);
                        }
                    }
                }
                "flag" => {
                    if errors_only && is_valid { continue; }
                    let obj = json!({
                        "instance": inst_path,
                        "output": "flag",
                        "payload": {"valid": is_valid},
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                }
                "list" => {
                    if errors_only && is_valid { continue; }
                    let payload = root_node.to_list_payload();
                    let obj = json!({
                        "instance": inst_path,
                        "output": "list",
                        "payload": payload,
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                }
                "hierarchical" => {
                    if errors_only && is_valid { continue; }
                    let payload = root_node.to_hierarchical_json();
                    let obj = json!({
                        "instance": inst_path,
                        "output": "hierarchical",
                        "payload": payload,
                        "schema": schema_path_str
                    });
                    println!("{}", obj);
                }
                _ => {}
            }
        }
        std::process::exit(overall_exit);
    }
}
